export default [{"id":684,"question":"حكم صلة الأرحام؟","title":"ما حكم صلة الرحم؟","answer":"الجواب: واجبة، يقول النبي ﷺ: من أحب أن يبسط له في رزقه وأن ينسأ له في أثره فليصل رحمه، ويقول في الحديث الصحيح الآخر في الرحم: من وصلها وصلته، ومن قطعها بتته، والله يقول: فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ  ۝  أُولَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23]، وفي الحديث الآخر: لا يدخل الجنة قاطع رحم.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6831/ما-حكم-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/maram252 - 03 - .mp3","categories":["فضائل الأعمال"]},{"id":1503,"question":"هل ثبت في أجر المُصْلح (بين الناس) حديث أنه كقائم الليل صائم النهار؟","title":"ما فضل وكيفية الإصلاح بين الناس؟","answer":"الجواب:\nجاء في حديث: ألا أُنَبِّئكم بخير أعمالكم؟ إصلاح ذات البين، وقال: وفساد ذات البين هي الحالقة، لا أقول: تحلق الشعر، ولكن تحلق الدِّين، فالمقصود أن الإصلاح بين الناس فيه خيرٌ كثيرٌ.\nس: بعضهم يُزَكِّي طائفةً إلى الطائفة الثانية وهم ليسوا أهلًا، ويقول: هذا من الكذب الذي يجوز؟\nج: إذا كان للإصلاح بينهم فلا بأس، يقول: هم يزكونكم، ويُثنون عليكم، ويقول للآخرين: يثنون عليكم، حتى يجمع بينهم الصلح، من باب الإصلاح بينهم.\nس: مع أنه يقول: عقيدتهم طيبة، وهم ليسوا كذلك؟\nج: لا، إذا كان شيئًا يُصلح بينهم يقول: رَبْعُكم يثنون عليكم، يقول: رَبْعنا، ونُحب أن نُصلح بينهم، ونُحب أن نصلح ما بيننا، وإن هم إلا خير، ونحو هذا، فليس يكذب في العقيدة، إنما يكذب في الإصلاح بينهم.","link":"https://binbaz.org.sa/fatwas/21602/ما-فضل-وكيفية-الاصلاح-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فضل إصلاح ذات البين وما يتعلق به.mp3","categories":["فضائل الأعمال"]},{"id":2396,"question":"ألا يكون الرباط في المسجد؟","title":"بِمَ يحصل فضل \"الرباط\" في انتظار الصلاة؟","answer":"الجواب:\nنعم؟ فذلكم الرباط كما سماه النبي ﷺ، سماه \"رباط\"، الجلوس في المسجد لانتظار الصلاة رباط، وهكذا انتظارها، ولو ما جلس وهي على باله؛ يراقب وقتها حتى يحضر؛ فهو في رباط.","link":"https://binbaz.org.sa/fatwas/22521/بم-يحصل-فضل-الرباط-في-انتظار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرباط في المسجد.mp3","categories":["فضائل الأعمال"]},{"id":2475,"question":"قراءة سورة الكهف يوم الجمعة؟","title":"ما حكم قراءة سورة الكهف يوم الجمعة؟","answer":"الجواب:\nمستحبة، جاء فيها حديث فيه ضعف، وجاء موقوفًا على أبي سعيد الخدري وبعض الصحابة.\nس: من نسيها في النهار يقضيها في الليل؟\nالشيخ: سُنة فات محلها في النهار يوم الجمعة.","link":"https://binbaz.org.sa/fatwas/22604/ما-حكم-قراءة-سورة-الكهف-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قراءة سورة الكهف يوم الجمعة.mp3","categories":["فضائل الأعمال"]},{"id":2776,"question":"بالنسبة لصلاة الجماعة وصلاة الفرد أفضل بسبع وعشرين درجة، هل هي درجة حسنة أم درجة من درجات الجنة؟","title":"ما معنى الدرجة في حديث: «بسبع وعشرين درجة»؟","answer":"الجواب: المضاعفة، مضاعفة الأجر، الدرجات هي الأجر؛ مضاعفة الأجر.","link":"https://binbaz.org.sa/fatwas/22924/ما-معنى-الدرجة-في-حديث-بسبع-وعشرين-درجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة الجماعة أفضل بسبع وعشرين درجةهل هي درجة حسنة أم درجة من درجات الجنة.mp3","categories":["فضائل الأعمال","صلاة الجماعة"]},{"id":3741,"question":"من أحسن إلى نفس رطبة له صدقة؟","title":"هل فضل الإحسان إلى الحيوان مثل بني آدم؟","answer":"الجواب: لفظ الحديث كل كبد رطبة فيها أجر، يعني حتى من غير بني آدم، مثل الكلب يعطيه، مثل الهر، مثل أشباهه نعم. ولكن بني آدم أعظم، الصدقة فيهم أعظم وأكمل.","link":"https://binbaz.org.sa/fatwas/23933/هل-فضل-الاحسان-الى-الحيوان-مثل-بني-ادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإحسان إلى نفس رطبة.mp3","categories":["فضائل الأعمال"]},{"id":4829,"question":"حكم صلة الأرحام؟","title":"ما حكم صلة الأرحام؟","answer":"واجبة، يقول النبيُّ ﷺ في الحديث: مَن أحبَّ أن يبسط له في رزقه، وأن يُنسأ له في أثره فليصل رحمه، ويقول في الحديث الصحيح الآخر: يقول الله جلَّ وعلا في الرحم: مَن وصلها وصلتُه، ومَن قطعها بتتّه، والله يقول: فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ  ۝  أُولَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22- 23]، وفي الحديث الآخر: لا يدخل الجنةَ قاطعُ رحم.","link":"https://binbaz.org.sa/fatwas/25248/ما-حكم-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم صلة الأرحام.mp3","categories":["فضائل الأعمال"]},{"id":4838,"question":"أيّهما أفضل: التسبيح أو التَّهليل؟","title":"أيّهما أفضل التسبيح أو التَّهليل؟","answer":"التهليل أعظم، التهليل إثباتٌ لوحدانية الرب، والتَّسبيح تنزيه وتقديس، وكلها مُستحبة، كلها فيها الخير العظيم، لكن أفضل الكلام: لا إله إلا الله؛ لأنها إثبات التوحيد.","link":"https://binbaz.org.sa/fatwas/25272/ايهما-افضل-التسبيح-او-التهليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيّهما أفضل التسبيح أو التَّهليل.mp3","categories":["فضائل الأعمال","الأدعية والأذكار"]},{"id":4843,"question":"الصلاة على الأنبياء عند ورد ذكرهم في الآيات؟","title":"حكم الدعاء والصلاة على الأنبياء أثناء تلاوة الصلاة","answer":"ما أعلم فيه بأسًا. لكن في الفرض تركه أولى وإن فعله فالأمر واسع؛ لأن بعض أهل العلم ذكر أن الفرض كالنفل على القاعدة ولهذا قال الحنابلة ولو في فرض.\nس: والتعوذ بالله من النار وسؤال الجنة؟\nج: تركه أولى في الفريضة.","link":"https://binbaz.org.sa/fatwas/25283/حكم-الدعاء-والصلاة-على-الانبياء-اثناء-تلاوة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة على الأنبياء عند ورود ذكرهم في الآيات، والتعوذ بالله من النار وسؤال الجنة.mp3","categories":["فضائل الأعمال","الأدعية والأذكار"]},{"id":5664,"question":"ما حكم مَن خرج من بيته مُتطهِّرًا، كان له خطوة حسنة، وخطوة تمسح خطيئة، أو ما في معناه؟ ما رأيكم فيمَن يخرج غير مُتطهرٍ ويتطهر بالمسجد؟","title":"ما الأجر المترتب لمن يخرج من بيته مُتطهِّرًا؟","answer":"الجواب: الأفضل أن يتطهر في بيته، كما جاء في الحديث، فإذا خرج من بيته مُتطهِّرًا كتب الله له بكل خطوةٍ: يرفعه الله بها درجة، ويحطّ عنه بها خطيئة، ويكتب له بها حسنة، حتى يصل المسجد، ولا يزال في صلاةٍ ما انتظر الصَّلاة.[1]","link":"https://binbaz.org.sa/fatwas/31701/ما-الاجر-المترتب-لمن-يخرج-من-بيته-متطهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 010.mp3","categories":["فضائل الأعمال"]},{"id":5801,"question":"جاء في كتب السنة: أن مؤذن رسول الله كان يؤذن خارج المسجد على الباب، فهل هذه سنة واجبة، أم مستحبة؟","title":"هل صح أنه كان يُؤذَّن خارج المسجد؟","answer":"الجواب: لا، هذا حديث ضعيف رواه أبو داود بإسناد ضعيف؛ لأنه من طريق ابن إسحاق، وقد عنعن وهو مدلس، فحديثه ضعيف إذا دلس، وليس بثابت. والسنة في الأذان أن يكون على محل مرتفع، كما كان بلال يؤذن على السطح، حتى يكون أندى للصوت، وإذا كانت منارة كما صنع الناس المنارات فهو أندى، والآن جاءت المكبرات هذه؛ فاكتفى بها الناس؛ لأن تكبير الصوت يبلغ البعيد، ولهذا اكتفى بعضهم بها عن المنارة؛ لعدم الحاجة إلى المنارة.","link":"https://binbaz.org.sa/fatwas/1123/هل-صح-انه-كان-يوذن-خارج-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_129.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","الأذان والإقامة"]},{"id":6392,"question":"من هم الأقارب الذين تجب صلة الرحم معهم، وتكون واجبة في حقهم؟","title":"تحديد الأقارب الذين يجب صلتهم","answer":"الجواب: كل الأقارب يوصلون، لكنهم يتفاوتون في القرب، فكل من كان أقرب؛ صارت صلته أوجب، فأقربهم الآباء، والأمهات، وإن علوا، والأولاد وأولاد البنين، والبنات، وإن نزلوا، ثم يليهم الإخوة، والأخوات، ثم بنو الإخوة، وبنات الإخوة، ثم الأعمام، والعمات، وهكذا. يقول النبي -عليه الصلاة والسلام- لما سئل، قال له رجل: أي الناس أحق بالصحبة وفي لفظ بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟  قال: أمك قال: ثم من قال: أبوك، ثم الأقرب فالأقرب وفي اللفظ الآخر: يا رسول الله من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من في الرابعة قال: أباك، ثم الأقرب، فالأقرب فهو مأمور بأن يبر والديه، ثم الأقرب، فالأقرب، كأولاده، وإخوته، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/1968/تحديد-الاقارب-الذين-يجب-صلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_755.mp3","categories":["النيابة في الحج","إهداء القرب للميت","فضائل الأعمال"]},{"id":7024,"question":"إمام المسجد حينما تقام الصلاة يقف في المحراب، ويقول: أقامها الله وأدامها، اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه اللهم مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد، فهل هذا دعاء مأثور، أو هناك غيره، أو هذا أفضل؟","title":"حكم قول (أقامها الله وأدامها) عند إقامة الصلاة","answer":"الجواب:\n\nالأذان يقال فيه هذا، إذا فرغ من الأذان؛ يصلي على النبي ﷺ ويقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته هكذا جاء الحديث عن رسول الله ﷺ، فيما رواه البيهقي وزيادة: إنك لا تخلف الميعاد هذا سنة بعد الأذان، والإقامة أذان ثانٍ يقال بعدها.\n\nأما (أقامها الله وأدامها) جاء فيه حديث ضعيف، والأفضل أن يقول: قد قامت الصلاة مثل المؤذن، يقول: قد قامت الصلاة، قد قامت الصلاة، بدلا من (أقامها الله وأدامها) لأن لفظة أقامها الله وأدامها جاء فيه خبر ضعيف، لا يصح عن النبي ﷺ وإنما يقال مثل ما قال النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول يعني يقول: قد قامت الصلاة، قد قامت الصلاة، في أذان الفجر إذا قال: الصلاة خير من النوم، يقول: الصلاة خير من النوم مثلها.\n\nأما في حي على الصلاة، حي على الفلاح، فيقول: لا حول ولا قوة إلا بالله؛ لأنه صح به الخبر عن النبي ﷺ أنه كان يقول عند حي على الصلاة: لا حول ولا قوة إلا بالله وعند حي على الفلاح يقول: لا حول ولا قوة إلا بالله هذا في الأذان، والإقامة.\n\nالسؤال: يعني ما سمعنا يقول: اللهم رب هذه الدعوة ما كان؟\n\nالجواب: لا، لا، بعد الأذان وبعد الإقامة طبيعي؛ لأنها كلها أذان.\n\nالسؤال: بالنسبة في عمان إقامتهم مثل الأذان طبق الأصل؟\n\nالجواب: قول ثانٍ للعلماء، رواه أبو جحيفة، الأذان له أنواع، والإقامة لها أنواع، فلا بأس إذا كانوا يطبقون حديث أبي جحيفة، لا بأس مثل الأذان، نعم، لكن أذان بلال أفضل، الذي كان بين يدي النبي ﷺ إقامتنا، وأذاننا الآن.","link":"https://binbaz.org.sa/fatwas/2952/حكم-قول-اقامها-الله-وادامها-عند-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1403.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","الأذان والإقامة"]},{"id":7432,"question":"ما حكم من صلوا بدون أذان ولا إقامة؟ وهل الأذان واجب والإقامة؟ لأن شيخ الإسلام ابن تيمية قال: إذا أقيم في بلد؛ سقط عن الباقين. وما حكم العزائم التي فيها زعفران يشربها المريض، إلى آخره؟","title":"حكم الصلاة بلا أذان ولا إقامة وكتابة الآيات للرُّقية","answer":"الجواب: الأذان والإقامة فرض كفاية، إذا كان في القرية أو في المدينة عليهم أن يؤذنوا ويقيموا، وهكذا في السفر عليهم أن يؤذنوا ويقيموا إذا كان المسجد واحدًا؛ فأذان واحد، وإن كان مسجدان أذانان، ثلاثة ثلاث، وهكذا على حسب المساجد، والإقامة فرض كفاية، إذا أقام المؤذن أو غيره؛ كفى، ولو صلوا ولم يؤذنوا ولم يقيموا؛ صحت صلاتهم، لكن يأثمون بترك الأذان والإقامة، يكونون قد أخطأوا وصلاتهم صحيحة؛ لأن هذا واجب خارج الصلاة فلا يضر الصلاة تركه من جهة عدم الصحة، بل صلاتهم صحيحة وهم آثمون وعليهم التوبة والاستغفار وعدم العود إلى ترك الأذان والإقامة. وكذلك كتابة الآيات القرآنية والدعوات بالزعفران في إناء أو في أوراق ثم يغسل ويشرب لا بأس به، وقد فعله كثير من السلف، ولكن كونه يقرأ على المريض، ينفث على يد المريض أو رجله، أو بماء يشربه؛ يكون هذا أفضل وأكمل.","link":"https://binbaz.org.sa/fatwas/3520/حكم-الصلاة-بلا-اذان-ولا-اقامة-وكتابة-الايات-للرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1824.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","الأذان والإقامة"]},{"id":7603,"question":"يقول أيضاً الطالب في معهد الجوف العلمي عبد الوهاب بن عمر المريح: ما حكم من صلى النافلة وهو جالس، مع العلم أنه يستطيع أن يصلي وهو قائم مع الدليل إن أمكن؟","title":"حكم من صلى النافلة جالساً مع قدرته على القيام","answer":"الجواب: قد ثبت عن رسول الله عليه الصلاة والسلام أنه كان يصلي في تهجده بالليل بعض الأحيان وهو قاعد، وفي بعض الأحيان يصلي وهو قائم عليه الصلاة والسلام، فهذا يدل على جواز أداء النافلة قاعداً؛ لأن الله قال: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]؛ ولأن النافلة مرغب فيها وفيها أجر عظيم، فمن رحمة الله أن وسع فيها حتى يصلي الإنسان ما تيسر، وحتى يستكثر من النوافل قاعداً وقائماً، أما الفريضة فلا يجوز الجلوس فيها إلا من عذر؛ لأن الله قال: وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]، وقال النبي ﷺ لـعمران بن حصين لما سأله عن ذلك، قال: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، وهذا في الفريضة، وهذا رواه البخاري في الصحيح، وفي رواية النسائي: فإن لم تستطع فمستلقياً، هذا حكم الفريضة، فالواجب على المسلمين أن يصلوها قياماً مع القدرة رجالاً ونساء، فمن عجز عن ذلك لمرض صلى قاعداً، أو لشبه مرض مثل مسجون في محل سقفه قصير لا يستطيع القيام فيه ولا يستطيع الخروج منه فإنه يصلي على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإن عجز عن القعود صلى على جنبه والأفضل الأيمن، فإن عجز عن الصلاة على جنب صلى مستلقياً ويومئ إيماءً ويأتي بالأذكار الشرعية، ويأتي بالأفعال بالنية، فيكبر، ويستفتح، ويقرأ الفاتحة، يستفتح ويتعوذ ويبسمل ويتعوذ ويقرأ الفاتحة وما تيسر معها، ثم يكبر ناوياً الركوع وهو على حاله مستلقياً أو على جنبه، يكبر ناوياً الركوع ويقول: سبحان ربي العظيم.. سبحان ربي العظيم.. سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ثم يرفع إذا كان مفرداً يقول: (سمع الله لمن حمده) ناوياً الرفع من الركوع وهو على حاله مستلقياً أو على جنبه، ثم يأتي بالذكر المشروع: ربنا ولك الحمد.. إلى آخره، ثم يكبر ناوياً السجود ويقول: سبحان ربي الأعلى.. سبحان ربي الأعلى.. إلى آخره، فيأتي بالأقوال ويأتي بالأفعال بالنية، الأقوال بلفظها والأذكار كذلك والدعوات، ويأتي بالأفعال بالنية نية الركوع، نية السجود، نية الجلوس هكذا، أما النافلة فأمرها بحمد الله موسع، إن صلى قائماً فهو أفضل، وإن صلى قاعداً فهو على النصف من أجر القائم، إذا كان قادراً وصلى جالساً في النافلة فصلاته صحيحة ولكنه على النصف من صلاة القائم، كما جاءت به السنة عن النبي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4656/حكم-من-صلى-النافلة-جالسا-مع-قدرته-على-القيام ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02103.mp3","categories":["القيام في الصلاة","فضائل الأعمال"]},{"id":8778,"question":"يقول: ما كيفية زيارة مسجد الرسول ﷺ؟ وهل الأدعية الواردة في كتيبات الزيارة التي يزور بها المزورون في الأماكن المقدسة صحيحة أم لا؟ وأرشدونا عن كيفية الزيارة الصحيحة؟","title":"ما هي الأعمال المستحبة عند زيارة مسجد النبي؟","answer":"الجواب: زيارة مسجد الرسول ﷺ سنة؛ لأنها أحد المساجد الثلاثة، وقد قال فيه النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى فشد الرحال إلى هذه الثلاثة سنة وقربة وطاعة، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام فقصد هذا المسجد العظيم للصلاة فيه والقراءة فيه والتعبد أمر مطلوب وشرعي، وهكذا المسجد الحرام مسجد مكة، وهكذا المسجد الأقصى القدس، كل هذه الثلاثة المساجد قصدها وشد الرحيل إليها قربة وطاعة، فإذا وصل إليها المؤمن صلى فيها ما يسر الله، وتعبد فيها بالاعتكاف أو بالقراءة أو بحضور حلقات العلم، كل هذا طيب. وأما مكة فيحصل فيها أيضاً زيادة على هذا: الطواف بالكعبة، ويمكن أداء العمرة كذلك والحج في وقته، هذا يختص بمكة، العمرة والحج هذا من خصائص مكة. أما مسجد النبي ﷺ فالزائر له مثل بقية المساجد يصلي فيه، يتعبد بالقراءة، بحضور حلقات العلم بالإكثار من ذكر الله ، كل هذا مطلوب، وهكذا الاعتكاف، وهكذا المسجد الأقصى إذا زاره المؤمن صلى فيه وقرأ فيه وذكر الله فيه وتعبد فيه بأنواع العبادة من الصلاة والذكر والقراءة والاعتكاف ونحو ذلك كل هذا مشروع.\nويستحب لمن زار المدينة: أن يسلم على النبي ﷺ وعلى صاحبيه، فيتوجه بعدما يصلي ركعتين في المسجد إذا صلاها في الروضة كان أفضل، إذا صلى الركعتين في الروضة كان أفضل وإن صلاها في بقية المسجد كفى ذلك، ثم بعد هذا يتوجه إلى قبره عليه الصلاة والسلام فيقف أمامه عليه الصلاة والسلام ويسلم عليه عليه الصلاة والسلام ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، صلى الله وسلم عليك وعلى آلك وأصحابك، ويدعو له، يقول: جزاك الله عن أمتك خيراً، أشهد أنك قد بلغت الرسالة، وأديت الأمانة، ونصحت الأمة، وجاهدت في الله حق جهاده.. إذا قال هذا الكلام هذا كلام طيب وصحيح وصدق، ثم يتقدم قليلاً فيسلم على الصديق  أبو بكر فيقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً.. رضي الله عنك، ثم يتقدم قليلاً ويسلم على عمر الفاروق  عمر بن الخطاب فيقول: السلام عليك يا عمر بن الخطاب ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً ورضي الله عنك، ويدعو لهما ثم ينصرف، هذا هو المشروع في السلام على الرسول ﷺ وعلى صاحبيه الصديق وعمر رضي الله تعالى عنهما.\nويشرع له أيضاً أن يزور البقيع فيسلم على أصحاب البقيع ويدعو لهم بالمغفرة والرحمة؛ لأن الرسول كان يزورهم عليه الصلاة والسلام، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية. هكذا يسلم على أهل القبور ويدعو لهم: اللهم اغفر لهم وارحمهم، مثلما دعا النبي ﷺ لأهل البقيع، وهكذا يستحب له أن يزور الشهداء شهداء أحد فيدعو لهم ويستغفر لهم ويترحم عليهم  وأرضاهم، هذا هو المشروع.\nأما ما يفعله بعض الجهلة كونه يدعو النبي ﷺ، أو يستغيث به، أو يتمسح بجدران الحجرة هذا منكر لا يجوز، ولكن يسلم وهو واقف من غير أن يمسح الحجرة أو القضبان أو الجدران أو الأسطوانات، كل هذا غير مشروع بل بدعة، لا يتمسح بالجدران ولا بالأسطوانات ولا بقضبان الشبك ولا بغير هذا، ولكن يقف أمام النبي ﷺ ويسلم وهكذ أمام الصديق ، وأمام عمر رضي الله عنهما ويسلم ثم ينصرف، هذا هو المشروع، ولا يدعو النبي ﷺ ولا يدعو غيره، لا يقل: يا رسول الله! انصرني أو اشفع لي، أو أغثني، أو المدد المدد، هذا منكر لا يجوز بل هو من الشرك الأكبر، وهكذا عند الصحابيين الصديق وعمر رضي الله عنهما لا يقل لهما: أغيثاني أو انصراني أو المدد المدد كما يفعل بعض الجهلة عند بعض القبور، هذا منكر، بل هذا من الشرك، طلب الغوث من الميت والمدد من الميت هذا من الشرك الأكبر عند أهل العلم، وهكذا عند زيارة قبور البقيع لا يقل لهم: المدد المدد، ولا انصروني، أو اشفوا مريضي، أو اشفعوا لي لا، ولكن يسلم عليهم ويدعو لهم بالمغفرة والرحمة ثم ينصرف، وهكذا شهداء أحد إذا سلم عليهم يدعو لهم كما دعا لهم النبي ﷺ ويستغفر لهم ويترحم عليهم وينصرف.\nويستحب لمن زار المدينة أيضاً أن يزور مسجد قباء ويصلي فيه ركعتين كما كان النبي يزوره عليه الصلاة والسلام، وأخبر ﷺ أن من زاره.. أن من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة. فزيارة مسجد قباء سنة وقربة تأسياً بالنبي عليه الصلاة والسلام في ذلك، هذا هو المشروع لمن زار المدينة، أما كونه يقصد محلات أخرى آبار أو مساجد أخرى أو بقاع هذا غير مشروع، المشروع لمن زار المدينة هو ما ذكرنا: أولاً: الصلاة في مسجد النبي ﷺ، ثم السلام على النبي ﷺ وعلى صاحبيه، ثم زيارة البقيع، ثم زيارة الشهداء، ثم زيارة مسجد قباء، كل هذه سنة وليست واجبة، لو أنه ما زارها ما فيه شيء، ولكن هذا سنة ومستحب وليس بواجب. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6933/ما-هي-الاعمال-المستحبة-عند-زيارة-مسجد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21906.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":8779,"question":"يقول: ما كيفية زيارة مسجد الرسول ﷺ؟ وهل الأدعية الواردة في كتيبات الزيارة التي يزور بها المزورون في الأماكن المقدسة صحيحة أم لا؟ وأرشدونا عن كيفية الزيارة الصحيحة؟","title":"ما هي الأعمال المستحبة عند زيارة مسجد النبي؟","answer":"الجواب: زيارة مسجد الرسول ﷺ سنة؛ لأنها أحد المساجد الثلاثة، وقد قال فيه النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى فشد الرحال إلى هذه الثلاثة سنة وقربة وطاعة، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام فقصد هذا المسجد العظيم للصلاة فيه والقراءة فيه والتعبد أمر مطلوب وشرعي، وهكذا المسجد الحرام مسجد مكة، وهكذا المسجد الأقصى القدس، كل هذه الثلاثة المساجد قصدها وشد الرحيل إليها قربة وطاعة، فإذا وصل إليها المؤمن صلى فيها ما يسر الله، وتعبد فيها بالاعتكاف أو بالقراءة أو بحضور حلقات العلم، كل هذا طيب. وأما مكة فيحصل فيها أيضاً زيادة على هذا: الطواف بالكعبة، ويمكن أداء العمرة كذلك والحج في وقته، هذا يختص بمكة، العمرة والحج هذا من خصائص مكة. أما مسجد النبي ﷺ فالزائر له مثل بقية المساجد يصلي فيه، يتعبد بالقراءة، بحضور حلقات العلم بالإكثار من ذكر الله ، كل هذا مطلوب، وهكذا الاعتكاف، وهكذا المسجد الأقصى إذا زاره المؤمن صلى فيه وقرأ فيه وذكر الله فيه وتعبد فيه بأنواع العبادة من الصلاة والذكر والقراءة والاعتكاف ونحو ذلك كل هذا مشروع.\nويستحب لمن زار المدينة: أن يسلم على النبي ﷺ وعلى صاحبيه، فيتوجه بعدما يصلي ركعتين في المسجد إذا صلاها في الروضة كان أفضل، إذا صلى الركعتين في الروضة كان أفضل وإن صلاها في بقية المسجد كفى ذلك، ثم بعد هذا يتوجه إلى قبره عليه الصلاة والسلام فيقف أمامه عليه الصلاة والسلام ويسلم عليه عليه الصلاة والسلام ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، صلى الله وسلم عليك وعلى آلك وأصحابك، ويدعو له، يقول: جزاك الله عن أمتك خيراً، أشهد أنك قد بلغت الرسالة، وأديت الأمانة، ونصحت الأمة، وجاهدت في الله حق جهاده.. إذا قال هذا الكلام هذا كلام طيب وصحيح وصدق، ثم يتقدم قليلاً فيسلم على الصديق  أبو بكر فيقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً.. رضي الله عنك، ثم يتقدم قليلاً ويسلم على عمر الفاروق  عمر بن الخطاب فيقول: السلام عليك يا عمر بن الخطاب ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً ورضي الله عنك، ويدعو لهما ثم ينصرف، هذا هو المشروع في السلام على الرسول ﷺ وعلى صاحبيه الصديق وعمر رضي الله تعالى عنهما.\nويشرع له أيضاً أن يزور البقيع فيسلم على أصحاب البقيع ويدعو لهم بالمغفرة والرحمة؛ لأن الرسول كان يزورهم عليه الصلاة والسلام، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية. هكذا يسلم على أهل القبور ويدعو لهم: اللهم اغفر لهم وارحمهم، مثلما دعا النبي ﷺ لأهل البقيع، وهكذا يستحب له أن يزور الشهداء شهداء أحد فيدعو لهم ويستغفر لهم ويترحم عليهم  وأرضاهم، هذا هو المشروع.\nأما ما يفعله بعض الجهلة كونه يدعو النبي ﷺ، أو يستغيث به، أو يتمسح بجدران الحجرة هذا منكر لا يجوز، ولكن يسلم وهو واقف من غير أن يمسح الحجرة أو القضبان أو الجدران أو الأسطوانات، كل هذا غير مشروع بل بدعة، لا يتمسح بالجدران ولا بالأسطوانات ولا بقضبان الشبك ولا بغير هذا، ولكن يقف أمام النبي ﷺ ويسلم وهكذ أمام الصديق ، وأمام عمر رضي الله عنهما ويسلم ثم ينصرف، هذا هو المشروع، ولا يدعو النبي ﷺ ولا يدعو غيره، لا يقل: يا رسول الله! انصرني أو اشفع لي، أو أغثني، أو المدد المدد، هذا منكر لا يجوز بل هو من الشرك الأكبر، وهكذا عند الصحابيين الصديق وعمر رضي الله عنهما لا يقل لهما: أغيثاني أو انصراني أو المدد المدد كما يفعل بعض الجهلة عند بعض القبور، هذا منكر، بل هذا من الشرك، طلب الغوث من الميت والمدد من الميت هذا من الشرك الأكبر عند أهل العلم، وهكذا عند زيارة قبور البقيع لا يقل لهم: المدد المدد، ولا انصروني، أو اشفوا مريضي، أو اشفعوا لي لا، ولكن يسلم عليهم ويدعو لهم بالمغفرة والرحمة ثم ينصرف، وهكذا شهداء أحد إذا سلم عليهم يدعو لهم كما دعا لهم النبي ﷺ ويستغفر لهم ويترحم عليهم وينصرف.\nويستحب لمن زار المدينة أيضاً أن يزور مسجد قباء ويصلي فيه ركعتين كما كان النبي يزوره عليه الصلاة والسلام، وأخبر ﷺ أن من زاره.. أن من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة. فزيارة مسجد قباء سنة وقربة تأسياً بالنبي عليه الصلاة والسلام في ذلك، هذا هو المشروع لمن زار المدينة، أما كونه يقصد محلات أخرى آبار أو مساجد أخرى أو بقاع هذا غير مشروع، المشروع لمن زار المدينة هو ما ذكرنا: أولاً: الصلاة في مسجد النبي ﷺ، ثم السلام على النبي ﷺ وعلى صاحبيه، ثم زيارة البقيع، ثم زيارة الشهداء، ثم زيارة مسجد قباء، كل هذه سنة وليست واجبة، لو أنه ما زارها ما فيه شيء، ولكن هذا سنة ومستحب وليس بواجب. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6933/ما-هي-الاعمال-المستحبة-عند-زيارة-مسجد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21906.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":8954,"question":"بارك الله فيكم. رسالة وصلت إلى البرنامج من العراق باعثها أحد الإخوة من هناك يقول: رمضان الطائي محافظة التأميم فيما يبدو، أخونا له مجموعة من الأسئلة نختار منها هذا السؤال يقول:إنني كثيراً ما أحفظ من الآيات من القرآن الكريم ولكنني بعد فترة أنساها، وكذلك عندما أقرأ آية فلا أعلم هل هي صحيحة أم لا، ثم أكتشف بعد ذلك أنني كنت مخطي، دلوني لو تكرمتم؟","title":"فضل حفظ القرآن وتعلمه ومجاهدة نسيانه","answer":"الجواب: المشروع لك يا أخي أن تجتهد في حفظ ما تيسر من كتاب الله، وأن تقرأ على أهل المعرفة من الإخوان الطيبين في المدارس أو في المساجد أو في البيت، وتحرص على ذلك، يقول النبي ﷺ: خيركم من تعلم القرآن وعلمه.\nخيار الناس أهل القرآن الذين تعلموه وعلموه الناس وعملوا به، ويقول ﷺ لبعض أصحابه: أيحب أحدكم أن يذهب إلى بطحان -إلى واد في المدينة- فيأتي بناقتين عظيمتين في غير إثم ولا قطيعة رحم؟ قالوا: يا رسول الله! كلنا يحب ذلك، فقال عليه الصلاة والسلام:: لأن يغدو أحدكم إلى المسجد فيتعلم آيتين من كتاب الله خير له من ناقتين عظيمتين، وثلاث خير من ثلاث، وأربع خير من أربع وأمثالهن من الإبل، فهذا يبين لنا فضل قراءة القرآن وتعلم القرآن، فأنت يا أخي تتعلم تتصل بالإخوان الطيبين في المساجد أو في المدارس أو في حلقات تحفيظ القرآن حتى تستفيد، وحتى تقرأ قراءة صحيحة.\nوأما ما يعرض من النسيان فلا حرج عليك، إذا نسيت بعض الشيء لا حرج، فالبشر ينسى، يقول النبي ﷺ: إنما أنا بشر أنسى كما تنسون، وسمع مرة قارئاً يقرأ فقال: رحم الله فلاناً لقد أذكرني آية كذا كنت أسقطتها، يعني: نسيتها.\nالمقصود أن الإنسان قد ينسى بعض الآيات، والأفضل أن يقول: نسيت؛ لأنه جاء في بعض الأحاديث أنه عليه الصلاة والسلام قال: لا يقولن أحدكم: نسيت آية كذا، نسيت آية كذا بل هو نسي، يعني: أنساه الشيطان، فلا يضرك أخي.\nأما حديث: من حفظ القرآن ثم نسيه لقي الله وهو أجذم، فهو حديث ضعيف عند أهل العلم لا يثبت عن النبي ﷺ، والنسيان ليس باختيار الإنسان وليس في طوقه قد ينسى مهما كان.\nفالمقصود أن المشروع لك أن تجتهد وتحرص على الحفظ، وتستعين بالله ثم بمن يتيسر من الإخوان في حفظ ما تيسر من كتاب الله، ثم تدرس ذلك وتعتني به وأبشر بالخير.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7113/فضل-حفظ-القران-وتعلمه-ومجاهدة-نسيانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_145/14503.mp3","categories":["فضائل الأعمال","شروح الحديث"]},{"id":10705,"question":"أرجو من سماحتكم مناقشة موضوع بر الوالدين، ذلكم أننا نلحظ أن كثيراً من الأبناء يعقون والديهم، وربما منعوا أبناءهم عن زيارة أجدادهم، والد يمنع ابنته عن زيارة جدتها، أي: عن زيارة أمه، وسبب المنع خلاف بين الجدة وابنها، أرجو التفصيل في هذا الموضوع وفي بر الوالدين بالذات، جزاكم الله خيراً؟","title":"ما جاء في الكتاب والسنة في فضل بر الوالدين","answer":"الجواب: لا ريب أن بر الوالدين من أهم الفرائض ومن أعظم الواجبات، والله سبحانه وتعالى ذكر ذلك في مواضع كثيرة من كتابه العظيم، مثل قوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:24] ومثل قوله سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا [النساء:36]، ومثل قوله جل وعلا: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] في آيات كثيرات فيها الحث على بر الوالدين، وفيها الأمر بذلك.\nوقد صح عن رسول الله ﷺ ما يدل على هذا المعنى أيضاً، فسئل عليه الصلاة والسلام قيل: يا رسول الله! أي العمل أفضل؟ قال: الصلاة على وقتها. قيل: ثم أي؟ قال: بر الوالدين. قيل: ثم أي؟ قال: الجهاد في سبيل الله، وفي الصحيحين عن أبي بكرة الثقفي  عن النبي ﷺ أنه قال : ألا أنبئكم بأكبر الكبائر -كررها ثلاثاً- قالوا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين، وكان متكئاً فجلس، فقال: ألا وقول الزور ألا وشهادة الزور.\nفبين عليه الصلاة والسلام أن من أكبر الكبائر العقوق للوالدين؛ فبرهما من أهم الواجبات ومن أعظم الفرائض، وعقوقهما من أقبح الكبائر والسيئات.\nوفي الحديث الآخر: رضا الله في رضا الوالدين وسخط الله في سخط الوالدين، فالواجب على كل مسلم وعلى كل مسلمة بر الوالدين والإحسان إليهما والرفق بهما والأدب معهما في القول والعمل، ومن ذلك أن ينفق عليهما إذا كانا فقيرين وهو يستطيع النفقة، ومن ذلك مخاطبتهما بالتي هي أحسن بالكلام الطيب والأسلوب الحسن وخفض الصوت، وعدم رفع الصوت عليهما، ومن ذلك السمع والطاعة لهما في المعروف إذا أمراه بشيء لا يخالف شرع الله وهو يستطيعه لا يضره ذلك، يطيعهما بالكلام الطيب والفعل الطيب.\nومن ذلك أن لا يحبس أولاده عن زيارة والديه، إذا رغب الوالد أو الوالدة في زيارة أولاده يزوروه، أن يمكن الأولاد من زيارة الوالدين فليس له أن يمنع أولاده ذكوراً كانوا أو إناثاً من زيارة أمه أو أبيه، إلا أن يكون هناك ضرر لأن الوالد يأمرهما بمعاصي يأمر أولاده بمعاصي الله، أو الوالدة هذا له منع ذلك؛ لأن طاعة الله مقدمة، أما إذا كان ليس هناك ضرر في أن يزوروه والوالد يحسن إليهم والوالدة كذلك ولا يترتب على الزيارة معصية لله فليس له أن يمنع أولاده من زيارة أبويه، بل هذا من برهما أن يمكن أولاده يزوروهم ويأنسوا بهم ويتمتعوا بالاجتماع بهم.\nالمقصود: أن من بر الوالدين أن تسمح لأولادك بزيارتهما حتى يستمتعا بأولادك ويجتمعا بهما ويأنسا بهما، وربما ترتب على ذلك مصالح كثيرة، لكن إذا كان الوالدان يأمران أولادك بمعاصي الله أو يحصل منهما على الأولاد ضرر بضرب أو غيره من غير علة فلك أن تمنع، لقول النبي ﷺ: لا ضرر ولا ضرار، أما أن تمنع أولادك من والديك من دون حق ومن دون سبب هذا لا يجوز، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8880/ما-جاء-في-الكتاب-والسنة-في-فضل-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34204.mp3","categories":["فضائل الأعمال"]},{"id":10971,"question":"هذه سائلة للبرنامج أرسلت بهذا السؤال، ملخص السؤال -سماحة الشيخ- تقول هذه السائلة: نقرأ سورة البقرة في بيت، وسمعت بأن من قرأ سورة البقرة في البيت لا يقربه شيطان ثلاثة أيام، و هل يلزم علينا أن نقرأ هذه السورة العظيمة؟","title":"فضل قراءة سورة البقرة في البيت","answer":"الجواب:  ثبت في الحديث الصحيح أن الرسول ﷺ قال: اجعلوا من صلاتكم في بيوتكم، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة هذا يدل على أن قراءة سورة البقرة، وقراءة القرآن والإكثار من الذكر من أسباب طرد الشيطان والحماية من شره، فيشرع للمرأة وللرجل أن يكون لهم نصيب من القراءة في البيت من قراءة القرآن، والإكثار من ذكر الله؛ لأن ذلك من أسباب السلامة من شر عدو الله الشيطان، الله يقول سبحانه: وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف:36] ومعنى (يعش) يعني: يغفل ويعرض، فالغفلة عن ذكر الله، وعن قراءة القرآن من أسباب استيلاء الشياطين على الإنسان، وكثرة الوساوس، والهموم، وكثرة القراءة للقرآن، وكثرة الذكر والتسبيح والتهليل والاستغفار من أسباب طرد الشيطان، ومن أسباب سلامة القلب من الوساوس والهواجس الضارة، فنوصي من يستمع هذا البرنامج نوصيه بالإكثار من ذكر الله، من قراءة القرآن في الليل والنهار، في جميع الأوقات في التسبيح والتهليل، فإن هذا كله من أسباب الحماية من عدو الله، ومن أسباب عدم الوساوس ومن أسباب طرد الشياطين من بيتك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ! تقول في فقرة أخرى يا سماحة الشيخ: هل يكفي أن نفتح شريطًا بصوت أي قارئ، ونحن نستمع فقط، وهل يشترط أن نقرأ هذه السورة في جلسة واحدة، أو نستمع إليها باستماع متواصل من بداية السورة حتى نهاية السورة. الشيخ: هذا هو المستحب السماع، يستحب لكم السماع للقارئ، وإذا قرأتم بأنفسكم فهو خير، والحمد لله يستحب لكم سماع القارئ والإنصات والتدبر والتعقل، النبي ﷺ: أمر عبدالله بن مسعود في بعض الأيام في بعض المجالس أن يقرأ عليه القرآن، فقال عبدالله: يا رسول الله! كيف أقرأ عليك وعليك أنزل؟ قال -عليه الصلاة والسلام-: إني أحب أن أسمعه من غيري، فقرأ عليه عبدالله بن مسعود أول سورة النساء، حتى بلغ قوله تعالى: فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا [النساء:41] قال النبي: حسبك، قال عبدالله بن مسعود فالتفت إليه فإذا عيناه تذرفان، عليه الصلاة والسلام. والله يقول: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] فالمؤمن يقرأ.. ويقول ﷺ: اقرؤوا القرآن فإنه يأتي شفيعًا لأصحابه يوم القيامة فالمؤمن يقرأ في بيته، ويصلي النوافل في بيته، ويكثر من التسبيح والتهليل والتحميد والاستغفار والدعاء، كل هذا من أسباب المغفرة ومن أسباب رضا الله، ومن أسباب انشراح الصدر، وقوة الإيمان، ومن أسباب طرد الشياطين. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9149/فضل-قراءة-سورة-البقرة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28615.mp3","categories":["فضائل الأعمال"]},{"id":11027,"question":"تقول: إن زوجي يأخذ مبلغًا شهريًا من راتبه، ويخصصه لأحد أقاربه المحتاجين، وأنا أشجعه على ذلك، وأشجعه على صلة رحمه، فهل لي أجر على ذلك بخصوص الصدقة، أم أنه هو فقط الذي يأخذ الأجر على أساس أنه من راتبه هو، وأنا لا أعمل، وهل في معاملتي لأهل زوجي ثواب؛ لأنهم ليسوا من ذوي الأرحام؟","title":"فضل إعانة المرأة زوجها على صلة رحمه","answer":"الجواب:  قد أحسنت في ذلك ولك أجر عظيم، وهو له أجر عظيم، جزاه الله خيرًا، وله بشرى بالخلف من عند الله والأجر، يقول الله سبحانه: وَمَا أَنفَقْتُمْ مِنْ شَيْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ [سبأ:39]، ويقول  في كتابه العظيم: مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا [البقرة:245]، ويقول سبحانه: وَمَا تُقَدِّمُوا لِأَنْفُسِكُمْ مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا [المزمل:20]، ويقول النبي ﷺ: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله فليصل رحمه، ويقول في الرحم، يقول الله : من وصلها وصلته، ومن قطعها قطعته. وأنت لك أجر في التشجيع والترغيب، لك أجر عظيم؛ لأن عملك من باب الإعانة على الخير، ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه، والله يقول سبحانه في كتابه العظيم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، فأنت لك أجر وأبشري بالخير، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9205/فضل-اعانة-المراة-زوجها-على-صلة-رحمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36706.mp3","categories":["فضائل الأعمال"]},{"id":11551,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية محافظة الرقة، باعث الرسالة المستمع: موسى الدرويش بن دحام أخونا يسأل جمعًا من الأسئلة، في أحدها يقول: هل الذي يحفظ سورة البقرة فقط تظله يوم القيامة؟","title":"فضائل قراءة القرآن والعمل به","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. \nفقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: يؤتى بأهل القرآن يوم القيامة الذين يعلمون به، تقدمه سورة البقرة وآل عمران؛ تحاجان عن أصحابهما يوم القيامة، كأنهما غمامتان، أو غيايتان، أو فرقان من طير صواف، تحاجان عن أصحابهما. فهذا الحديث الصحيح، وما جاء في معناه يدل على أن البقرة وآل عمران تحاجان عن أصحابهما الذين يعملون بالقرآن، لأنه قال: بأهله العاملين به فالقرآن حجة لمن عمل به كله، القرآن كله حجة، ومن أسباب سعادة العبد، فإن القرآن يشفع له يوم القيامة ويشفع، وهكذا هاتان السورتان العظيمتان تحاجان عن أصحابهما العاملين بهما، وإذا كان الرجل يحفظ سورة البقرة، ويعمل بها هي أيضًا تحاج عن صاحبها، وإن لم يحفظها، إذا كان يعمل بها؛ فإنها حجة له من أسباب دخوله الجنة. فجدير بالمؤمن أن يعتني بالحفظ العملي، وإذا لم يتيسر الحفظ فالمهم العمل، كونه يقرأ ولو نظرًا، يقرأ ويعتني ويعمل، وإن تيسر الحفظ؛ فهذا خير إلى خير، ونور إلى نور، لكن الأهم من هذا كله العمل، كونه يقرأ القرآن، ويعمل به، سواءً حفظه، أم لم يحفظه؛ فهو حجة له، وهكذا البقرة، وآل عمران حجة له إذا عمل بذلك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9734/فضاىل-قراءة-القران-والعمل-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38601.mp3","categories":["فضائل الأعمال","شروح الحديث"]},{"id":11665,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف: (خ. ع. ص. ب) من السودان الخرطوم، أخونا له جمع من الأسئلة من بينها سؤال يقول: إنني أقرأ بعد صلاة العصر كل يوم جزأين من القرآن الكريم، توجيهكم في هذا؟ جزاكم الله خيرًا.","title":"فضل تلاوة القرآن الكريم وآدابه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقراءة القرآن الكريم مشروعة دائمًا في جميع الأوقات من ليل ونهار، والقرآن هو كلام الله  وهو أفضل الكلام، وهو منزل غير مخلوق، منه بدأ وإليه يعود، فهو كلامه سبحانه كسائر صفاته، كالعلم والرحمة والرضا والغضب والسمع والبصر كلها صفات له -جل وعلا- تليق به  فكلامه يليق به، لا يشابه كلام غيره -جل وعلا- وهو أفضل كتاب، وأفضل كلام، جعله الله هداية للعباد، وموعظة وذكرى وتبصيرًا، قال تعالى: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قال سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًىى وَشِفَاءٌ [فصلت:44]، قال سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89]، فإذا قرأه الإنسان بعد العصر، أو بعد الصبح، أو في جميع الأوقات كله خير. وقراءته بعد العصر فيه فائدة؛ لأن الذكر في آخر النهار في المساء أمر مطلوب. وهكذا في أول النهار مطلوب، وهو أفضل الذكر وأعظم الذكر، لكن يشرع للقارئ أن يعتني بالقراءة، وأن تكون عن خشوع وتدبر وتعقل ورغبة في الفائدة، كما قال سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، وقال سبحانه: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]. فالمشروع للقارئ من الرجال والنساء أن يتدبر، ويتعقل، وأن يعتني بالمعاني حتى يستفيد، ثم يعمل، سواء كانت القراءة من المصحف، أو عن ظهر قلب، والمشروع للإنسان أن يتحرى الأوقات المناسبة التي يكون فيها خشوعه أكثر، وتدبره أكثر، في العصر، أو في الليل، أو في آخر الليل، أو في أول الصباح، يلتمس الأوقات المناسبة التي يرجو فيها أن تكون قراءته أكمل من جهة الخشوع والتدبر والتعقل والإقبال على معاني القرآن، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: من قرأ حرفًَا من القرآن؛ فله حسنة، والحسنة بعشر أمثالها، لا أقول: (الم) حرف، ولكن ألف حرف، ولام حرف، وميم حرف، فهذا فضل من الله، جل وعلا. وقال -عليه الصلاة والسلام-: اقرؤوا القرآن فإنه يأتي شفيعًا لأصحابه يوم القيامة وقال ﷺ: يدعى بالقرآن يوم القيامة وأهله الذين كانوا يعملون به، تقدمه سورة البقرة وآل عمران تحاجان عن أصحابهما. وقال -عليه الصلاة والسلام- يومًا لأصحابه: من يحب منكم أن يذهب إلى بطحان -وادي في المدينة- فيأتي بناقتين عظيمتين من غير إثم ولا قطيعة رحم؟ قالوا: كلنا نحب ذلك يا رسول الله، قال -عليه الصلاة والسلام-: لأن يغدو أحدكم إلى المسجد، فيعلم آية من كتاب الله خير له من ناقتين عظيمتين، وثلاث خير من ثلاث، وأربع خير من أربع، ومن أعدادهن من الإبل أو كما قال -عليه الصلاة والسلام- فهذا يدل على فضل القراءة والتعلم. ويقول ﷺ: خيركم من تعلم القرآن وعلمه خيار الناس أهل القرآن تعلمًا وتعليمًا وعملًا، ويقول أيضًا -عليه الصلاة والسلام-: والقرآن حجة لك أو عليك في حديث أبي مالك الأشعري قال -عليه الصلاة والسلام-: الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن أو قال: تملأ ما بين السماء والأرض، والصلاة نور، والصدقة برهان، والصبر ضياء، والقرآن حجة لك أو عليك، كل الناس يغدو فبائع نفسه فمعتقها أو موبقها، خرجه مسلم في صحيحه. فالمقصود: أن القرآن حجة لك إذا عملت به، واستقمت عليه، وحجة عليك إذا أضعته، ولم تستقم عليه، فالواجب على صاحب القرآن أن يعتني بالقرآن علمًا وعملًا، وأن يحذر التخلف عن أوامر القرآن، أو ارتكاب نواهي القرآن، بل يكون حريصًا على فعل الأوامر، وترك النواهي، حريصًا على التدبر والتعقل، يرجو ثواب الله، ويخشى عقابه  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9848/فضل-تلاوة-القران-الكريم-وادابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29901.mp3","categories":["فضائل الأعمال"]},{"id":11938,"question":"إذا استمعت إلى القرآن الكريم من شريط، أو أي إذاعة، فهل لي الأجر؟","title":"فضل استماع القرآن الكريم","answer":"الجواب:  نعم، إذا استمعت للقراءة؛ فأنت مأجور، داخل في قوله تعالى: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204]، فأنت على خير عظيم، والمستمع شريك للقارئ بكل حرف حسنة، والحسنة بعشر أمثالها، فنوصي جميع إخواننا المسلمين العناية بسماع القرآن، بالاستماع له من القراء، ومن إذاعة القرآن، وإذا جلسوا جميعًا قرأ عليهم أحدهم، واستمعوا له، واستفادوا وتدبروا، فهذا فيه خير عظيم، وكان النبي ﷺ إذا اجتمع بأصحابه يقرأ القرآن ويعلمهم، وإذا مر بالسجدة سجد وسجدوا معه -عليه الصلاة والسلام- وربما أمر بعض الصحابة أن يقرأ عليه -عليه الصلاة والسلام- وأمر مرة عبدالله بن مسعود أن يقرأ، فقرأ أول سورة النساء، والنبي يستمع له -عليه الصلاة والسلام- فلما بلغ قوله تعالى: فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلاءِ شَهِيدًا [النساء:41] قال له: حسبك، قال ابن مسعود : فالتفت إليه، فإذا عيناه تذرفان، تذكر هذا الموقف -عليه الصلاة والسلام- فبكى، عليه الصلاة والسلام. والمقصود: أن الاجتماع على قراءة القرآن والاجتماع: ..... القرآن والإنصات والتدبر والتعقل فيه خير عظيم، واستماعه من الراديو، من إذاعة القرآن فيه خير أيضًا، ومصالح كثيرة، فنوصي باستماع القرآن، والتدبر، والتأمل، والعمل، كما نوصي بالإكثار من قراءة القرآن في بيتك، وفي المسجد، وفي الطريق، وفي الطائرة، وفي القطار، وفي السيارة، تجتهد في قراءة القرآن بالتدبر، والتعقل، كما قال سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، وقال -عليه الصلاة والسلام-: من قرأ القرآن؛ فله بكلل حرف حسنة، والحسنة بعشر أمثالها وقال أيضًا -عليه الصلاة والسلام-: اقرءوا القرآن؛ فإنه يأتي شفيعًا لأصحابه يوم القيامة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10123/فضل-استماع-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42802.mp3","categories":["فضائل الأعمال"]},{"id":12358,"question":"تقول أختنا: علمت أن من يقرأ سورة الإخلاص ثلاث مرات، وسورة الكافرون ثلاث مرات، فكأنما قرأ القرآن كله، فهل هذا صحيح؟","title":"فضل قراءة سورة الإخلاص والكافرون","answer":"الجواب:  نعم ثبت عن النبي ﷺ أن قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] تعدل ثلث القرآن، تعدل ثلث القرآن، فإذا كررها ثلاثًا .... ختمة، لكن لا يغني ذلك عن قراءة القرآن، يشرع له هذا وهذا، يشرع قراءة قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] ويشرع له أن يقرأ القرآن كله من أوله إلى آخره، حتى يتدبره، وله بكل حرف حسنة، والحسنة بعشر أمثالها، فيشرع له أن يقرأ القرآن، وأن يكثر من تلاوته، ومع هذا يقرأ قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] أيضًا؛ لأنها سورة عظيمة، تعدل ثلث القرآن، والمؤمن والمؤمنة مشروع لهما التدبر والتعقل، والإكثار من التلاوة، لقصد العلم والفهم، ومعرفة الأحكام الشرعية، ولقصد الفضل والثواب الذي رتبه الله على القراءة.  المقدم: جزاكم الله خيرًا، بالنسبة للكافرون حفظكم الله؟ الشيخ: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] ورد فيها ما يدل على أنها تعدل ربع القرآن، ولكن لا أذكر الآن صحته .... يتيسر في حلقة أخرى الإيضاح في هذا الأمر، إيضاح ما يتعلق بالكافرون، هل ثبت الحديث فيها، أنها تعدل ربع القرآن، أم لا؟ ويكون هذا -إن شاء الله- في حلقة أخرى، إن شاء الله. المقدم: إن شاء الله، وأنتم على خير، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/10562/فضل-قراءة-سورة-الاخلاص-والكافرون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39920.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":12395,"question":"السؤال الأخير لأخينا يقول: حدثونا عن ابتلاء المسلم في الدنيا بالمرض والفقر.","title":"فضائل الصبر على البلاء","answer":"الجواب:  هذا الأمر أخبر النبي ﷺ عنه، قال ﷺ: أشد الناس بلاء الأنبياء، ثم الصالحون، ثم الأمثل فالأمثل، يبتلى المرء على قدر دينه، فإن كان في دينه صلابة؛ شدد عليه في البلاء والله نبه على هذا في آيات كثيرات، قال : وَبَلَوْنَاهُمْ بِالْحَسَنَاتِ وَالسَّيِّئَاتِ لَعَلَّهُمْ يَرْجِعُونَ [الأعراف:168] بِالْحَسَنَاتِ النعم وَالسَّيِّئَاتِالمصائب لَعَلَّهُمْ يَرْجِعُونَ يعني: ليرجعوا إلى طاعة الله، وإلى التوبة إليه، وإلى النظر فيما ينفعهم إلى غير ذلك، قال تعالى: وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً [الأنبياء:35] وقال تعالى: وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الأَمْوَالِ وَالأَنفُسِ وَالثَّمَرَاتِ وَبَشِّرِ الصَّابِرِينَ [البقرة:155] والآيات في هذا المعنى كثيرة، بين سبحانه أنه يبتلي عباده لحكم وأسرار، والله -جل وعلا- يختبر عباده، فمن شكر؛ صارت العاقبة حميدة، ومن كفر؛ صارت العاقبة وخيمة، ولهذا قال: فِتْنَةٌ يعني: اختبارًا وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً [الأنبياء:35] يعني: اختبارًا وامتحانًا.  فكن أنت عبدًا صالحًا، إذا ابتليت؛ فاصبر، وصابر، واجتهد في طاعة الله، وأد الحق الذي عليك؛ حتى تكون بهذا الابتلاء ناجحًا موفقًا، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10600/فضاىل-الصبر-على-البلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40119.mp3","categories":["الرقائق","فضائل الأعمال"]},{"id":12408,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (ب. س) من الرياض تسأل وتقول: ورد في الحديث أن من جلس بعد صلاة الفجر إلى طلوع الشمس على مصلاه يذكر الله حتى يصلي ركعتي الفجر؛ كتبت له أجر حجة وعمرة، وقال أهل العلم: إن المرأة إذا فعلت ذلك في بيتها يرجى لها نصف الأجر،  هناك أناس يقولون: إنه يشترط لهذه الجلسة ألا يتحدث مع أحد في أمور الدنيا، هل هذا الكلام صحيح، وإذا كان صحيحًا، فماذا أفعل إذا كانت والدتي كبيرة في السن، وقد أخبرتها بذلك، ولكنها تنسى، وتحدثني بأمور دنيوية، لا ضرورة لها خلال جلستي هذه، فهل إذا جلست مبتغيةً الثواب من الله، ولكن تحدثت مع أمي، وأجبتها حرصًا على رضاها، هل أكون قد أديت العبادة كما ينبغي؟","title":"هل تدخل المرأة في فضل الجلوس بعد الفجر إلى الإشراق؟","answer":"الجواب:  نعم نعم جمعت بين الخيرين، بين الذكر، وبين رضا الوالدة، وبرها من أهم المهمات، فالحديث معها إذا طلبت الحديث أمر مطلوب، ومشروع، ولا يضر، ولا يقطع الجلسة، ولا يؤثر عليك، فمن جلس في مصلاه يذكر الله، يصلي على النبي ﷺ ويسبح، ويدعو حتى تطلع الشمس، ثم يصلي ركعتين سنة الضحى، هاتان الركعتان يقال لها: سنة الضحى، ويسميها العامة سنة الإشراق، وهي سنة الضحى مبكرة، فله أجر، جاء في الحديث: أجر حجة وعمرة تامتين. ولا فرق بين الرجال والنساء، المرأة كالرجل ما هو النصف، نصف حجة، لا حجة تامة، الرجل والمرأة سواء في هذا، الحديث عام للرجال والنساء، فالمرأة في بيتها تجلس في مصلاها، والرجل في مصلاه في المسجد حتى تطلع الشمس، ثم يصلي ركعتين، هذا كله خير عظيم، يشتغل بذكر الله، بالدعاء، بقراءة القرآن، الحمد لله، وإذا تكلم مع أخيه في شيء دعت إليه الحاجة؛ فلا بأس، أو تكلمت المرأة مع زوجها، أو مع والدتها، أو مع غيرهم في الحاجة؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الذين قالوا: إن المرأة لها نصف الأجر ليسوا على صواب؟ الشيخ: غلط، لا الأجر عام، الحكم واحد، فالرجل والمرأة سواء. المقدم: بارك الله فيكم، وسواء كان ذلك في المسجد، أو في بيتها. الشيخ: نعم نعم في المسجد، أو في البيت. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10620/هل-تدخل-المراة-في-فضل-الجلوس-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40208.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":12415,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (ب. س) من الرياض تسأل وتقول: ورد في الحديث أن من جلس بعد صلاة الفجر إلى طلوع الشمس على مصلاه يذكر الله حتى يصلي ركعتي الفجر؛ كتبت له أجر حجة وعمرة، وقال أهل العلم: إن المرأة إذا فعلت ذلك في بيتها يرجى لها نصف الأجر،  هناك أناس يقولون: إنه يشترط لهذه الجلسة ألا يتحدث مع أحد في أمور الدنيا، هل هذا الكلام صحيح، وإذا كان صحيحًا، فماذا أفعل إذا كانت والدتي كبيرة في السن، وقد أخبرتها بذلك، ولكنها تنسى، وتحدثني بأمور دنيوية، لا ضرورة لها خلال جلستي هذه، فهل إذا جلست مبتغيةً الثواب من الله، ولكن تحدثت مع أمي، وأجبتها حرصًا على رضاها، هل أكون قد أديت العبادة كما ينبغي؟","title":"هل تدخل المرأة في فضل الجلوس بعد الفجر إلى الإشراق؟","answer":"الجواب:  نعم نعم جمعت بين الخيرين، بين الذكر، وبين رضا الوالدة، وبرها من أهم المهمات، فالحديث معها إذا طلبت الحديث أمر مطلوب، ومشروع، ولا يضر، ولا يقطع الجلسة، ولا يؤثر عليك، فمن جلس في مصلاه يذكر الله، يصلي على النبي ﷺ ويسبح، ويدعو حتى تطلع الشمس، ثم يصلي ركعتين سنة الضحى، هاتان الركعتان يقال لها: سنة الضحى، ويسميها العامة سنة الإشراق، وهي سنة الضحى مبكرة، فله أجر، جاء في الحديث: أجر حجة وعمرة تامتين. ولا فرق بين الرجال والنساء، المرأة كالرجل ما هو النصف، نصف حجة، لا حجة تامة، الرجل والمرأة سواء في هذا، الحديث عام للرجال والنساء، فالمرأة في بيتها تجلس في مصلاها، والرجل في مصلاه في المسجد حتى تطلع الشمس، ثم يصلي ركعتين، هذا كله خير عظيم، يشتغل بذكر الله، بالدعاء، بقراءة القرآن، الحمد لله، وإذا تكلم مع أخيه في شيء دعت إليه الحاجة؛ فلا بأس، أو تكلمت المرأة مع زوجها، أو مع والدتها، أو مع غيرهم في الحاجة؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الذين قالوا: إن المرأة لها نصف الأجر ليسوا على صواب؟ الشيخ: غلط، لا الأجر عام، الحكم واحد، فالرجل والمرأة سواء. المقدم: بارك الله فيكم، وسواء كان ذلك في المسجد، أو في بيتها. الشيخ: نعم نعم في المسجد، أو في البيت. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10620/هل-تدخل-المراة-في-فضل-الجلوس-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40208.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":12570,"question":"هل يحاسب الشهيد الذي لم يستشهد في ساعة المعركة، والشهداء أقسام -كما نعلم-؟ وهل يشفع في سبعين فردًا؟ وهل يحاسب على كل شيء؟ وهل يعفى عنه في كل شيء إلا على الدين؟","title":"من فضائل الشهيد","answer":"الجواب:  جاء في الأحاديث الصحيحة أن الشهيد يغفر له كل شيء إلا الدين، فالشهيد الذي قتل في سبيل الله صابرًا محتسبًا مقبلًا غير مدبر؛ يغفر له كل شيء، كما قاله النبي -عليه الصلاة والسلام- إلا الدين قال: فإن جبرائيل أخبرني بذلك وأن صاحب الدين لا يضيع حقه، بل يرضيه الله عن حقه، ويعطيه حقه يوم القيامة، ولا يضيع عليه شيئًا، والشهيد يغفر له كل شيء، لكن الدين الذي عليه الله يقضيه عنه  لا يضيع على صاحبه، نعم. المقدم: جزاكم الله خيرًا، الشهيد الذي لم يستشهد في المعركة. الجواب: ما دام مات بسبب الجراحات؛ فهو شهيد، ما دام بسبب الجراحات التي ..... بها في سبيل الله صابرًا محتسبًا مقبلًا، غير مدبر، سواء مات في المعركة، أو تأخر موته أيامًا وليالي، لكنه مات بسبب الجراحات التي أصابته. المقدم: جزاكم الله خيرًا، لعلها تقصد من سؤالها سماحة الشيخ أقسام الشهداء الآخرين؟  الجواب: الشهداء أقسام، لكن أفضلهم شهيد المعركة في سبيل الله  ومنهم المطعون: الذي يموت بالطاعون، والمبطون الذي يموت بالإسهال في البطن، وصاحب الهدم الذي يموت بالهدم يسقط عليه جدار أو سقف، وفي حكمه من يموت بدهس السيارات، وانقلاب السيارات، وصدام السيارات هذا من جنس الهدم، وكذلك الغرق، كل هذه أنواع من الشهادة، لكن أفضلهم شهيد المعركة، وهو الذي لا يغسل، ولا يصلى عليه، أما البقية يغسلون، ويصلى عليهم، وإن كانوا شهداء، نعم. المقدم: جزاكم الله خيرًا، هل يشفعون؟ هل يعفى عن كل شيء عملوه إلا عن الدين، أم أن ذلك خاص. الجواب: هكذا جاء الحديث الصحيح في شهيد المعركة، وأنه إذا كان صابرًا محتسبًا، مقبلًا غير مدبر، هذا جاء في شهيد المعركة، أما غيرهم فالله أعلم، لهم فضل، ولهم خير، ولكن كونهم يشفعون في كذا، أو كونهم يغفر لهم كل شيء هذا محل نظر، يحتاج إلى دليل خاص، لكن لهم فضل، فضل الشهادة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10775/من-فضاىل-الشهيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41109.mp3","categories":["فضائل الأعمال"]},{"id":13308,"question":"هذا السائل أيضًا إبراهيم عبدالعزيز يقول: ماذا ورد في فضل قراءة آية الكرسي بعد كل صلاة فريضة؟","title":"فضل قراءة آية الكرسي عقب الصلوات","answer":"الجواب: سنة ورد فيها عدة أحاديث، بعضها ضعيف، وبعضها جيد، فهي سنة بعد كل صلاة اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] بعد الصلوات الخمس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11594/فضل-قراءة-اية-الكرسي-عقب-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52110.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","القرآن وعلومه"]},{"id":13331,"question":"هذه السائلة: (ع) من جازان صبيا، تقول في هذا  سماحة الشيخ! سؤالي يتكون من ثلاث فقرات: أولًا: ما هي حدود الصبر في الابتلاء؟ وما هي مراتب الصابرين؟ وما جزاء الصابرين على الابتلاء؟ وجهونا في ضوء هذه الفقرات مأجورين؟","title":"مراتب الصبر وفضله","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الله سبحانه أوجب على عباده الصبر عند المصائب، فقال سبحانه: وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [الأنفال:46] قال -جل وعلا-: وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّه [النحل:127] قال سبحانه: وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الأَمْوَالِ وَالأَنفُسِ وَالثَّمَرَاتِ وَبَشِّرِ الصَّابِرِينَ  ۝  الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ  ۝  أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157]. والصبر واجب، وهو كف اللسان عن النياحة، كف اليد عن خمش الوجه، أو شق الثوب، أو نحو ذلك، كون الإنسان يكف يده عما لا ينبغي، ويكف لسانه عما لا ينبغي، وقلبه لا يجزع هكذا، ولهذا قال -عليه الصلاة والسلام-: أنا بريء من الصالقة والحالقة والشاقة. الصالقة: التي ترفع صوتها عند المصيبة، والحالقة: التي تحلق شعرها عند المصيبة، والشاقة: تشق ثوبها عند المصيبة. وقال ﷺ: ليس منا من ضرب الخدود، أو شق الجيوب، أو دعا بدعوى الجاهلية. فالصابر هو الذي يكف جوارحه عما لا ينبغي، ويكف لسانه عما لا ينبغي، ويعمر قلبه بالطمأنينة والاحتساب، وعدم الجزع، والإيمان بأن الله سبحانه هو الحكيم العليم، وأنه -جل وعلا- يقدر المصائب لحكمة بالغة، يقدر على هذا مرض.. على هذا حادث سيارة.. على هذا موت.. على هذا إيذاء من فلان، أو فلان.. إلى غير ذلك، له الحكمة البالغة، ولهذا في الحديث الصحيح يقول النبي ﷺ: عجبًا لأمر المؤمن إن أمره كله له خير، وليس ذلك لأحد إلا للمؤمن، إن أصابته ضراء صبر؛ فكان خيرًا له، وإن أصابته سراء شكر؛ فكان خيرًا له هذا شأن المؤمن. والصبر واجب متعين، بحيث يكف يده ولسانه وجوارحه كلها عما لا ينبغي، فلا ينوح ولا يشق ثوبًا، ولا يلطم خدًا، بل يحتسب، ويصبر، ويعلم أن ذلك من عند الله، فيحتسب ذلك، ويكف جوارحه عما لا ينبغي. وإن رضي بهذا، واطمأن إليه، ورضي بما قدر الله له، كان أعظم وأكبر وأفضل؛ لقوله ﷺ: إن عظم الجزاء مع عظم البلاء، وإن الله إذا أحب قومًا ابتلاهم، فمن رضي؛ فله الرضا، ومن سخط؛ فله السخط. فالصبر واجب، والرضا سنة مؤكدة، والجزع محرم، الجزع والنياحة وشق الثوب ولطم الخد كل هذا محرم، فالجزع محرم، والصبر واجب، والرضا هو الكمال. وهناك مرتبة أخرى عليا، وهي: اعتبار المصيبة نعمة، يشكر الله عليها؛ فيكون شاكرًا صابرًا راضيًا شاكرًا، يرى أن المصيبة نعمة، هذا المرض الذي أصابه، أو فقر، أو خسارة في سلعة، أو نكبة في البدن، أو ما أشبه ذلك يراها نعمة، يشكر الله عليها، لما يترتب عليها من تكفير السيئات، وحط الخطايا، وعظم الأجور، فهو يعتبرها نعمة يصبر ويرضى ويحتسب، ويعتبرها نعمة يشكر الله عليها، هذه المرتبة العليا، الله المستعان. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11617/مراتب-الصبر-وفضله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54201.mp3","categories":["فضائل الأعمال"]},{"id":13332,"question":"هذا السائل عبدالرحمن من المدينة النبوية استعرضنا سؤالًا له، بقي له سؤالان، يقول: ثبت عن الرسول ﷺ أنه قال: من أتى مسجد قباء، وصلى فيه؛ كان كأجر عمرة والسؤال سماحة الشيخ: هل يشترط لهذه الصلاة الخروج، خصوصًا من البيت بنية الصلاة في قباء للحصول على أجر العمرة؟ أم أنه يأتي بأي صلاة تجزي؟ فمثلًا: إذا صليت الجمعة في قباء، فهل يكون لي أجر عمرة بمشيئة الله؟","title":"شرط الحصول على أجر العمرة للمصلي في قباء","answer":"الجواب:\n\nثبت عن النبي ﷺ: \"أنه كان يزور قباء كل سبت، راكبًا وماشيًا\" -عليه الصلاة والسلام- وقال -عليه الصلاة والسلام-: من تطهر في بيته، ثم أتى مسجد قباء، فصلى فيه ركعتين؛ كان كعمرة هذا الفضل ذكره لمن يتطهر من بيته، ويخرج قاصدًا للصلاة في قباء؛ يحصل له هذا الأجر.\n\nأما من صلى فيه كالعادة بغير قصد من بيته؛ فله أجر، وله خير عظيم، لكن لا يتوفر فيه الشرط المذكور، إنما يحصل هذا لمن تطهر في بيته، وخرج من بيته قاصدًا للصلاة في مسجد قباء، كما كان النبي يفعل، عليه الصلاة والسلام.\n\nأما الصلاة فيه من غير قصد من البيت، بل مر، وصلى به، أو كان من جيرانه، وصلى فيه الفروض؛ يرجى له خير عظيم؛ لكن لا يتوفر فيه ما قاله النبي ﷺ إلا بالشروط التي قالها: من تطهر في بيته، ثم أتى مسجد قباء، وصلى فيه يعني: يخرج من بيته قاصدًا، فإذا خرج من بيته قاصدًا يوم الجمعة، أو غير الجمعة، وصلى فيه؛ يحصل له هذا الأجر، والحمد لله. نعم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11618/شرط-الحصول-على-اجر-العمرة-للمصلي-في-قباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54202.mp3","categories":["شروح الحديث","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":13469,"question":"ننتقل بعد ذلك إلى الرياض والسائلة: (هـ. أ. م) لها مجموعة من الأسئلة، تبدأ هذه الرسالة وتقول: هل فضل صلاة المرأة في بيتها تعدل فضل صلاة الرجل في المسجد؟","title":"فضل صلاة المرأة في بيتها","answer":"الجواب: يقول النبي ﷺ: أفضل صلاة المرأة في بيتها فلها فضل عظيم، قد يكون مثل المسجد، وقد يكون أفضل، وقد يكون أقل، المقصود: أن أفضل صلاتها في البيت، فإذا كان فضلها في البيت أفضل من المسجد معناه أنه يحصل لها مثل أجر المسجد، أو أكثر؛ لأن الرسول ﷺ قال: أفضل صلاة المرأة في بيتها فدل على أن الأجر الذي يحصل للرجل في المسجد يحصل لها، أو ما هو أكثر منه لطاعتها لله ورسوله، وخضوعها لأمر الله ورسوله، هي على خير عظيم؛ ولأن بيتها أصون لها، وأبعد عن الفتنة. فإذا أطاعت الرسول ﷺ وصلت في البيت؛ يرجى لها مثل أجر المصلي في المسجد، أو أكثر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11772/فضل-صلاة-المراة-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51717.mp3","categories":["فضائل الأعمال","صلاة الجماعة"]},{"id":13472,"question":"لعلنا نختم هذا المجلس الطيب المبارك من برنامج نور على الدرب بهذا السؤال للسائلة: (هـ . أ. م) تقول: هل ثواب وأجر من يستمع إلى القرآن الكريم عبر الأشرطة مثل ثواب وأجر من يقرأ؛ لأنني أستمع كثيرًا للقراءة عبر الأشرطة؟ هل ينقص أجري في ذلك؟","title":"هل أجر سماع القرآن مثل من يقرأ؟","answer":"الجواب: نرجو لك الأجر في ذلك، وأنه مثل القارئ؛ لأن المستمع كالقارئ، فالذي يستمع شريك للقارئ، فإذا استمع بنية صالحة، وإخلاص يريد الفائدة؛ فنرجو له مثل أجر القارئ، فهما في الأجر سواء القاري والمستمع. فنوصي جميع إخواننا في الله من الرجال والنساء بالعناية بسماع القرآن، والتدبر والتعقل، فالذي يقرأ يقرأ ويتدبر، والذي لا يقرأ يستمع من الأشرطة، من نور على الدرب، هذا خير عظيم، من إذاعة القرآن يستمع الفوائد، ونرجو له في ذلك الخير العظيم. فالمستمع الراغب فيما عند الله، المخلص لله شريك القارئ، له أجر عظيم، يكون له مثل أجر القاري، أو أعظم إذا كان عن إخلاص، وعن صدق، وعن رغبة فيما عند الله  نعم.","link":"https://binbaz.org.sa/fatwas/11774/هل-اجر-سماع-القران-مثل-من-يقرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51719.mp3","categories":["فضائل الأعمال","القرآن وعلومه"]},{"id":13662,"question":"من أسئلة هذه السائلة تقول: ما هي صلاة الأوابين؟ وهل كان الرسول ﷺ يداوم على صلاتها، وماذا كان يقرأ فيها؟","title":"صلاة الأوابين وحكم المداومة عليها","answer":"الجواب: صلاة الأوابين صلاة الضحى إذا اشتد الضحى، هذه صلاة الأوابين، إذا اشتد الضحى؛ سن لكل أحد أن يصلي صلاة الضحى ركعتين، وإن زاد فلا بأس، النبي ﷺ أوصى أبا هريرة وأوصى أبا الدرداء بركعتي صلاة الضحى، وقال -عليه الصلاة والسلام-: يصبح على كل سلامى من أحدكم صدقة، فكل تسبيحة صدقة، وكل تهليلة صدقة، وكل تحميدة صدقة، أمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويكفي من ذلك ركعتان تركعهما من الضحى أو كما قال، عليه الصلاة والسلام. فجعل الركعتين تقومان مقام هذه الصدقات، وهذه التسبيحات والتكبيرات، وربما صلى الضحى ﷺ أربعًا، وربما صلاها ثمان -عليه الصلاة والسلام- صلاها يوم الفتح ثمان ركعات، أربع تسليمات، قالت عائشة: كان يصليها أربعًا، ويزيد ما شاء الله يعني: بعض الأحيان، عليه الصلاة والسلام. وما كان يداوم عليها؛ لئلا يشق على أمته، بل يترك العمل وهو يحب أن يعمله؛ مخافة المشقة على أمته، لكن دلت السنة القولية على أن المواظبة عليها، والمحافظة عليها سنة مؤكدة، كونه سيحافظ على صلاة الضحى، سنة مؤكدة من وصية النبي ﷺ فإنه أوصى بها -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11999/صلاة-الاوابين-وحكم-المداومة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52905.mp3","categories":["فضائل الأعمال","صلاة التطوع"]},{"id":13719,"question":"عند المرور أثناء القراءة على آية جنة، أو وعيد، أو ذكر للنار، هل نطلب من الله  العفو والمغفرة، ونطلبه الجنة، ثم نستعيذ بالله، ونسمي عند الاستمرار في القراءة؟","title":"هل يُسأل الله ويُستعاذ به عند آيات الوعد والوعيد؟","answer":"الجواب: لا مانع لا مانع، النبي ﷺ كان إذا قرأ في تهجده بالليل يقف عند كل آية فيها رحمة يسأل، أو آية وعيد يتعوذ، أو آية تعظيم يعظم الله، ويسبحه، فلا مانع من كون المسجل للقرآن إذا سجل شيئًا فيه ذكر الجنة أن يسأل الله الجنة، أو ذكر شيئًا فيه ذكر النار أن يتعوذ بالله من النار، أو إذا شيء فيه ذكر أسماء الله، وصفاته يقول:  سبحانه وبحمده ونحو هذا. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12090/هل-يسال-الله-ويستعاذ-به-عند-ايات-الوعد-والوعيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48109.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":13779,"question":"يسأل أخونا ويقول: أرجو توضيح بر الوالدين أثناء حياتهم وبعد مماتهم؟","title":"كيفية بر الوالدين في الحياة وبعد الممات","answer":"الجواب: بر الوالدين من أهم الواجبات والفرائض، وقد أمر الله بذلك في كتابه الكريم في آيات كثيرات؛ منها قوله سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا [النساء:36]، ومنها قوله  في سورة سبحان: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:24]، ومنها قوله سبحانه في سورة لقمان: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] فبرهما من أهم الفرائض حيين وميتين:\nفبرهما في الحياة: الإحسان إليهما والإنفاق عليهما إذا كانا محتاجين، والسمع والطاعة لهما في المعروف، وخفض الجناح لهما، وعدم رفع الصوت عليهما، والدفاع عنهما في كل شيء يضرهما.. إلى غير هذا من وجوه الخير.\nوالخلاصة: أن الولد يكون حريصًا على جلب الخير إليهما ودفع الشر عنهما في الحياة والموت؛ لأنهما قد أحسنا إليه إحسانًا عظيمًا في حال الصغر وربياه وأكرماه وتعبا عليه، فالواجب عليه أن يقابل المعروف بالمعروف والإحسان بالإحسان، والأم حقها أعظم، كما قال النبي عليه الصلاة والسلام لما سئل قيل: يا رسول الله! من أحق الناس بحسن صحابتي؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أبوك، وفي اللفظ الآخر قال: يا رسول الله! من أحق الناس بالبر؟، وفي اللفظ الآخر قال: من أبر يا رسول الله؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب. فبين عليه الصلاة والسلام أن أحق الناس بالبر والإحسان أمك ثلاث مرات ثم أبوك في الرابعة، وهذا يوجب للولد العناية بالوالدة أكثر والإحسان إليها أكمل، ثم الأب يليها بعد ذلك فبرهما والإحسان إليهما جميعًا أمر مفترض، وحق الوالدة على الولد الذكر والأنثى أعظم وأكبر.\nوسئل النبي ﷺ عن حق الوالدين بعد وفاتهما فقال له سائل: يا رسول الله! هل بقي من بر أبوي شيء أبرهما بعد وفاتهما؟ قال: نعم، الصلاة عليهما والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما.\nذكر خمسة أشياء: الصلاة عليهما الدعاء؛ ومن ذلك صلاة الجنازة فإنها دعاء والصلاة عليهما بالدعاء والترحم عليهما من أحق الحق ومن أفضل البر في الحياة والموت.\nوهكذا الاستغفار لهما، يعني: سؤال الله أن يغفر لهما سيئاتهما هذا أيضًا من برهما حيين وميتين.\nوإنفاذ عهدهما من بعدهما الوصية التي يوصيان بها، فالواجب على الولد ذكرًا كان أو أنثى إنفاذها إذا كانت موافقة للشرع المطهر.\nوالخصلة الرابعة: إكرام صديقهما إذا كان لأبيك أو أمك أصدقاء وأحباب وأقارب تحسن إليهم وتقدر لهم صحبة والديك وصداقة والديك ولا تنس ذلك، لا تنس ذلك بالكلام الطيب والإحسان إذا كانا في حاجة إلى الإحسان، وجميع أنواع الخير الذي تستطيعه فهذا من برهما بعد وفاتهما.\nوالخصلة الخامسة: صلة الرحم الذي لا توصل إلا بهما وذلك بالإحسان إلى أعمامك وأقارب أبيك وإلى أخوالك وخالاتك من أقارب أمك، هذا من الإحسان إلى الوالدين وبر الوالدين أن تحسن إلى أقارب والديك؛ الأعمام والعمات وأولادهم.. والأخوال والخالات وأولادهم، الإحسان إليهم وصلتهم كل ذلك من صلة الأبوين ومن إكرام الأبوين. وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12140/كيفية-بر-الوالدين-في-الحياة-وبعد-الممات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60102.mp3","categories":["فضائل الأعمال"]},{"id":14373,"question":"هذه السائلة تقول: هل النية بالإنفاق في سبيل الله عند الفقير يدرك بها أجر الغني المتصدق؟ وما معنى قول النبي ﷺ للفقراء لما جاؤوه: ذلك فضل الله يؤتيه من يشاء؟","title":"هل يؤجر الفقير بنية الإنفاق في سبيل الله؟","answer":"الجواب: نعم، الفقراء يؤجرون بنيتهم، أنه لو قدروا لفعلوا، فإذا كان عنده نية صالحة لو قدر لأنفق، لجاهد، يكون له أجر المجاهدين والمنفقين، وهكذا جاء الحديث، يقول ﷺ يقول في تبوك: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا إلا وهم معكم وفي لفظ: إلا شاركوكم في الأجر قالوا: يا رسول الله، وهم في المدينة؟! قال: وهم في المدينة، حبسهم العذر. وقال ﷺ: إذا سافر العبد أو مرض كتب الله له ما كان يعمل وهو صحيح مقيم هذا من فضل الله -جل وعلا-، إذا كان إنما منعه من أعماله السفر والمرض هذا له أجر العاملين، أما إنسان معرض غافل ما يكون له أجر العاملين وهو غافل ساهٍ معرض ما عنده مبالاة، سواء مرض أو ما مرض، سافر أو ما سافر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12854/هل-يوجر-الفقير-بنية-الانفاق-في-سبيل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55116.mp3","categories":["فضائل الأعمال","الرقائق"]},{"id":14526,"question":"في أدعية الصباح والمساء، نقرأ سورة الإخلاص ثلاث مرات، وكذلك المعوذات، سؤالي: هل أتعوذ وأبسمل عند قراءة السورة نفسها في كل مرة؟","title":"هل تقرأ الاستعاذة والبسملة عند قراءة السورة أكثر من مرة؟","answer":"الجواب: التعوذ عند أول ما تبدأ، أول ما تبدأ تأتي بالاستعاذة، أما التسمية تكررها، كلما قرأت السورة تكرر التسمية؛ لأن التسمية أمام السورة، تقرأ معها دائمًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13021/هل-تقرا-الاستعاذة-والبسملة-عند-قراءة-السورة-اكثر-من-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63404.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":14609,"question":"المستمعة (ف. ع. ع) من المدينة المنورة، بعثت برسالة ضمنتها بعض الأسئلة، تقول في أحدها:هل هناك أدعية تقال عند قراءة القرآن من أجل الحفظ؟","title":"هل توجد أدعية تقال من أجل حفظ القرآن؟","answer":"الجواب: ما نعلم شيئًا من أجل الحفظ خاص، لكن يسأل ربه، ويستعين بالله، يسأل ربه أن الله يوفقه للحفظ، ويلجأ إليه في أوقات الإجابة، مع الصدق، والله يعينه ، مثل الأوقات التي مثل آخر الليل، مثل جوف الليل، مثل آخر الصلاة، مثل السجود في الصلاة، مثل بين الأذان والإقامة، يقول: يا رب حفظني كتابك، يا رب أعني على حفظ كتابك، يسأل ويصدق في السؤال، ونسأل الله أن يسهل أمره. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13105/هل-توجد-ادعية-تقال-من-اجل-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48913.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":14911,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع: (ش. ق .ع) من ليبيا، أخونا عرضنا بعض أسئلته في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد، يقول فيه:أرجو منكم أن توضحوا لنا عن الزيارة للأقارب والأصدقاء، نريد فضل الزيارة، وما هي الأيام المستحب فيها الزيارة؟جزاكم الله خيرًا.","title":"فضل زيارة الأقارب والإخوان","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن الزيارة للإخوان في الله والأصدقاء والأقارب؛ تقربًا إلى الله، وطاعةً له سبحانه، وحرصًا على بقاء المودة والمحبة، وعلى صلة الرحم، من أفضل القربات، ومن أفضل الطاعات، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: يقول الله : وجبت محبتي للمتزاورين فيَّ، والمتجالسين فيَّ، والمتحابين فيَّ، والمتباذلين فيَّ وقال -عليه الصلاة والسلام-: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله، اجتمعا على ذلك، وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال؛ فقال: إني أخاف الله، ورجل تصدق بصدقة فأخفاها؛ حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليًا؛ ففاضت عيناه. هذا الحديث العظيم يدل على فضل التحاب في الله، ومن جملة التحاب في الله التزاور لتثبيت المودة، وللتعاون على الخير، والتواصي بالحق، وفي الصحيح أن رجلًا زار أخًا له في الله، فأرصد الله على طريقه ملكًا في صورة رجل، فلما مر عليه سأله، قال: أين تريد؟ قال: فلان قال: أردت فلانًا قال: هل لك من نعمة تربها عليه؟ قال: لا؛ إلا أني أحبه في الله، فقال له الملك: إني رسول الله إليك؛ أن الله أحبك كما أحببته فهذا يدل على فضل التزاور في الله للقريب والصديق، ثم في زيارة القريب صلة رحم أيضًا، وفي الحديث الصحيح يقول -عليه الصلاة والسلام-: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله؛ فليصل رحمه ويقول -عليه الصلاة والسلام-: لا يدخل الجنة قاطع رحم فصلة الرحم من أفضل القربات، وقطيعتها من أقبح السيئات، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13409/فضل-زيارة-الاقارب-والاخوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64001.mp3","categories":["فضائل الأعمال"]},{"id":15391,"question":"هذا السائل (ج. ر) من بريدة يقول: أسأل عن فضل الذكر وعن منزلته، مثلًا: هل أقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، هل تذكر على هذه الصفة، أو أقول: سبحان الله ثلاثًا وثلاثين، ثم أنتهي وأقول: الحمد لله ثلاثًا وثلاثين؟وجهوني بهذا، جزاكم الله خيرًا.","title":"فضل الذكر والحض على بعض الأذكار","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه،أما بعد: فالذكر له شأن عظيم، وهو من أفضل الأعمال، وأفضله قراءة القرآن، أفضل الذكر كلام الله ، ثم ما شرعه الله لعباده من التسبيح والتحميد والتهليل والتكبير، وقول: لا حول ولا قوة إلا بالله والدعاء، كله من الذكر، يقول الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا ۝ وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا [الأحزاب:41-42] ويقول -جل وعلا-: فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلا تَكْفُرُونِ [البقرة:152] ويقول -جل وعلا-: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْقَانِتِينَ وَالْقَانِتَاتِ [الأحزاب:35] إلى أن قال سبحانه: وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35] وقال -جل وعلا-: فَإِذَا قُضِيَتِ الصَّلاةُ فَانتَشِرُوا فِي الأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ وَاذْكُرُوا اللَّهَ كَثِيرًا لَعَلَّكُمْ تُفْلِحُونَ [الجمعة:10]. ويقول النبي ﷺ: سبق المفردون قالوا: يا رسول الله، ما المفردون؟ قال: الذاكرون الله كثيرًا والذاكرات قالت عائشة -رضي الله عنها-: \"كان النبي ﷺ يذكر الله على كل أحيانه\" كان -عليه الصلاة والسلام- يذكر الله على كل أحيانه، يعني: ليلًا ونهارًا، على طهارة وعلى غير طهارة. فهذا يبين لنا فضل الذكر، وأنه ينبغي للمؤمن أن يكثر منه، ولو كان على غير طهارة، الذي يحتاج إلى طهارة قراءة القرآن، لا يقرؤه الجنب، ولا يمس المصحف من كان محدثًا، وأما بقية الأذكار يقولها المحدث وغير المحدث، التسبيح والتهليل والتحميد والتكبير، قول: لا حول ولا قوة إلا بالله والاستغفار، كل هذا ذكر. والذكر بعد الصلاة أنت فيه مخير، إن شئت أفردت، وإن شئت جمعت، إن شئت جمعت قلت: سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، ثم تقول تمام المائة: لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير بعد كل صلاة من الصلوات الخمس، وإن شئت أفردت تقول: سبحان الله، سبحان الله، سبحان الله، ثلاثًا وثلاثين، ثم تقول: الحمد لله ثلاثًا وثلاثين، ثم الله أكبر ثلاثًا وثلاثين، الأمر في هذا واسع. ولك نوع آخر، وهو أن تقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر خمسة وعشرين مرة، تزيد فيها لا إله إلا الله، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، خمسة وعشرين مرة، بعد كل صلاة، أنت مخير بين هذا وهذا. ثم تقرأ آية الكرسي اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] ثم تقرأ قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] والمعوذتين بعد كل صلاة، وتكررها ثلاثًا بعد المغرب والفجر وعند النوم، وكان النبي ﷺ يكثر من التسبيح: سبحان الله وبحمده، سبحان الله العظيم، ويقول: حب الكلام إلى الله أربع يقول ﷺ: أحب الكلام إلى الله أربع: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر ويقول -عليه الصلاة والسلام-: الباقيات الصالحات: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله. وإذا تيسر لك أن تقرأ القرآن فالقرآن أفضل الذكر عن ظهر قلب، أو من المصحف، فذلك من أفضل الأعمال، كلام الله هو أفضل الذكر، ولك بكل حرف حسنة، والحسنة بعشر أمثالها، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13899/فضل-الذكر-والحض-على-بعض-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50001.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","القرآن وعلومه"]},{"id":16180,"question":"السائل يقول: هل يجوز لي قراءة آية الكرسي والمعوذتين مثلًا قبل النوم من غير وضوء، وبدون لمس المصحف؟","title":"حكم قراءة القرآن وأذكار النوم على غير وضوء","answer":"الجواب: نعم، إذا كونه على غير جنابة يقرؤهما، ولو كان ما هو على وضوء يقرأ آية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين عند النوم، ولو كان ما هو بعلى وضوء، لكن الأفضل أن ينام على وضوء، السنة أن يتوضأ، وينام على وضوء، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14844/حكم-قراءة-القران-واذكار-النوم-على-غير-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58008.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":16220,"question":"هذا السائل من خميس مشيط رمز لاسمه بـ (أ. ب. ج) يقول: سماحة الشيخ! ما هو فضل مجالسة الصالحين؟ وهل يؤجر الإنسان في ذلك مع أنه ليس عنده علم شرعي؟","title":"فضل مجالسة الصالحين","answer":"الجواب: نعم يشرع للمؤمن أن يلتمس الأخيار، وأن يجالسهم، أهل العلم، وأهل الدين، والإيمان الذين ليس عندهم شيء من المعاصي الظاهرة، أهل الخير المعروفين، يستحب العناية بمجالستهم حتى يستفيد منهم، وحتى يتأسى بهم في الخير، وحتى يبتعد عن أهل الشر. يقول النبي ﷺ: المرء على دين خليله، فلينظر أحدكم من يخالل ويقول ﷺ: مثل الجليس الصالح كحامل المسك: إما أن يحذيك يعني: يعطيك وإما أن تبتاع منه، وإما أن تجد منه ريحًا طيبة، ومثل الجليس السوء كنافخ الكير: إما أن يحرق ثيابك، وإما أن تجد منه ريحًا خبيثة. فالمؤمن يلتمس الأخيار، ويجالسهم، والمؤمنة كذلك تلتمس الخيِّرات، ويكون من جليساتها النساء الطيبات، هكذا المؤمن والمؤمنة، كل يلتمس الطيبين، المؤمن يلتمس الطيبين، والمؤمنة تلتمس الطيبات حتى يستفيد كل واحد من جلسائه الطيبين. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14895/فضل-مجالسة-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58013.mp3","categories":["فضائل الأعمال"]},{"id":16661,"question":"السائلة تقول في هذا السؤال يا سماحة الشيخ: هل الصبر على ما يحزن الإنسان، ويكدر من حياته يكون له أجر، وثواب، والرفعة في الدرجات؟","title":"فضل الصبر على المصائب","answer":"الجواب: نعم، الصبر على المصائب قربة إلى الله -جل وعلا- الله يقول: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157]، ويقول سبحانه: وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [الأنفال:46] ويقول -جل وعلا-: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10] ويقول النبي ﷺ: عجبًا لأمر المؤمن، وإن أمره كله له خير؛ إن أصابته ضراء؛ صبر، فكان خيرًا له، وإن أصابته سراء؛ شكر، فكان خيرًا له. فإذا أصاب المرأة، أو الرجل هموم، أو غموم من دين، أو من عداوة أحد، أو من عدوة والديه، أو من جيرانه، وصبر، ولم يفعل إلا الخير؛ فله أجر عظيم، وهكذا إذا صبر على الأمراض، والأحزان من موت القريب، كل ذلك فيه الخير العظيم، والفضل الكبير، نعم. المقدم: جزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15394/فضل-الصبر-على-المصاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58318.mp3","categories":["فضائل الأعمال"]},{"id":17075,"question":"يقول هذا السائل: هل بر الوالدين، والأعمال الصالحة تطيل في العمر؟","title":"إطالة العمر بالأعمال الصالحة وبر الوالدين","answer":"الجواب: بر الوالدين، والأعمال الصالحة من أعظم القربات، والبر من أسباب طول العمر، والبركة في العمر، كما في الحديث لا يزيد في العمر إلا البر.  فالبر من أسباب طول العمر، وبركته، وفي الحديث الصحيح: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله؛ فليصل رحمه وبر الوالدين من أعظم صلة الرحم، أعظم صلة الرحم، فبر الوالدين وصلة الرحم من أسباب طول العمر، والبركة في العمر. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15880/اطالة-العمر-بالاعمال-الصالحة-وبر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58815.mp3","categories":["فضائل الأعمال"]},{"id":17708,"question":"هذه الأخت السائلة أم مريم تقول: ما فضل آية الكرسي بعد كل صلاة واجبة، وهل تقرأ في كل الأحيان؟","title":"فضل قراءة آية الكرسي بعد الصلاة","answer":"الجواب: قراءة آية الكرسي بعد كل صلاة من الفريضة من أسباب دخول الجنة، فيستحب بعد الصلاة وبعد الأذكار أن يقرأ آية الكرسي بينه وبين نفسه، هذا مستحب جاء في عدة أحاديث مجموعها ترتقي إلى الحسن، فإذا قرأها بعد كل صلاة فهذا أفضل، ويستحب أن يقرأها عند النوم آية الكرسي أيضًا صح بها الحديث عن رسول الله ﷺ أنها من أسباب العافية من الشيطان والحفظ من الشيطان عند النوم إذا أراد أن ينام من الليل. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16661/فضل-قراءة-اية-الكرسي-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77616.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":17867,"question":"إذا مرض بعض أقاربي من النساء وكان هناك تنويم في المستشفى لكن لسن من المحارم هل لي زيارتهن في المستشفى؟الشيخ: أعد.المقدم: يقول: إذا مرض بعض أقاربي من النساء وكان هناك تنويم في المستشفى هل لي زيارتهن أو لا؟","title":"حكم زيارة المريضة من غير المحارم","answer":"الجواب: نعم، سن لك العيادة لهن وإن كن لسن محارم، تزورها بنت عمك أو زوجة أخيك أو زوجة عمك أو غيرهن من أقاربك أو جيرانك تزورهن وتدعو لهن بالعافية والشفاء من غير خلوة، يكون معك من يشاركك أو الممرضة التي عندها.\nفالحاصل من دون خلوة تدعو لها بالشفاء وتكون متحجبة مستورة والحمد لله هذا من مكارم الأخلاق، ومن محاسن الأعمال أن تزور زوجة أخيك أو زوجة عمك أو جارتك تدعو لها بالشفاء حتى تعلم هي وغيرها أن جيرانها وأقاربها يتأثرون بمرضها، والرسول ﷺ رغب في عيادة المرضى وإن كانوا ليس محارم، أمر بسبع منها عيادة المريض وقال: عودوا المريض عام  وأطعموا الجائع، وفكوا العاني، وقال: من عاد مريضًا صباحًا صلى عليه سبعون ألف ملك حتى يمسي، ومن عاد مريضًا مساءً صلى عليه سبعون ألف ملك حتى يصبح. فالعيادة للمرضى من أهم القربات ومن أفضلها وهي تعم الرجال والنساء والأقارب وغير الأقارب، لكن إذا كانت المرأة ليست محرمًا يكون معك من يشارك في ذلك حتى لا تخلو بها، وعليها أن تتستر إذا كانت تستطيع التستر أو يسترها غيرها من حولها من الممرضات أو القريبات يسترنها عند مجيء غير المحارم للسلام عليها والدعاء لها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16900/حكم-زيارة-المريضة-من-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84511.mp3","categories":["فضائل الأعمال"]},{"id":17908,"question":"يقول السائل في آخر أسئلته: ما هو الأجر من الله  في زيارة المريض؟ وإذا كلمه في التليفون هل يكفي هذا؟","title":"ما أجر زيارة المريض؟","answer":"الجواب: السنة أن يأتي المريض، الرسول أمر بعيادة المريض، أمر بعيادة المرضى عليه الصلاة والسلام، فقال: عودوا المريض، وأطعموا الجائع، وفكوا العاني. وقال البراء بن عازب: «أمرنا الرسول بسبع.. -ذكر منها:- عيادة المريض»، فالسنة أن يعود المريض، وإذا كلمه بالتلفون كان فيه فضل، لكن ليس مثل الذي يعوده؛ لأن كونه يعوده ويقصده في بيته أفضل، ولكن كونه يكلمه بالتليفون هذا على كل حال فيه خير وفيه فضل.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16925/ما-اجر-زيارة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59820.mp3","categories":["فضائل الأعمال"]},{"id":17991,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من المستمع مبارك إبراهيم من السودان الشمالية، يقول في أحد أسئلته: إذا كنت أعمل مع تاجر بإيجار وأريد تعلم القرآن، تكفل هذا التاجر بنفقة تعليمي واشترط الاشتراك في الأجر هل يجوز هذا؟","title":"فضل المساعدة على حفظ القرآن","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه.\nأما بعد:\nفلا شك أن المعاونة على تعليم القرآن والمساعدة في ذلك ليشترك في الثواب أمر مطلوب، وهو مأجور على إعانته لك في تعلم القرآن والاستفادة، والله جل وعلا لا يضيع عمل عامل، وهو القائل سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17013/فضل-المساعدة-على-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84901.mp3","categories":["فضائل الأعمال","القرآن وعلومه"]},{"id":18217,"question":"أعرفكم بأنني مداوم -والحمد لله- على صلاة الليل، لكني أرجو أن تعرفوني عن صلاة القيام في الوقت المحدد؟ وكم عدد ركعاتها؟ جزاكم الله خيرًا.","title":"فضل قيام الليل وأحكامه","answer":"الجواب: قيام الليل سنة مؤكدة، ومن عمل الصالحين، وهو دأب الصالحين، وهو من فعله ﷺ ومما كان يداوم عليه -عليه الصلاة والسلام- والله يقول في مدح عباد الرحمن، ويثني عليهم، فيقول: وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا [الفرقان:64]، ويقول في صفة المتقين: كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:17-18]، والله يقول لنبيه ﷺ: يَا أَيُّهَا الْمُزَّمِّلُ ۝ قُمِ اللَّيْلَ إِلَّا قَلِيلًا ۝ نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا ۝ أَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا [المزمل:1-4]. فالسنة قيام الليل، وآخر الليل أفضل من أوله، وإذا لم يتيسر له آخر الليل، أوتر في أول الليل، والوتر سنة مؤكدة، أقله ركعة، أقله ركعة واحدة، وإن أوتر بثلاث، أو بخمس، أو بأكثر؛ فهو أفضل، يسلم من كل ثنتين، هذا هو السنة، يسلم من كل ثنتين، وأفضله إحدى عشر ركعة، أو ثلاث عشر ركعة، النبي ﷺ كان النبي يوتر بإحدى عشرة، وربما أوتر بثلاث عشرة عليه الصلاة والسلام، هذا هو أفضل الوتر، يسلم من كل ثنتين، ويوتر بواحدة، وإن أوتر بأكثر: أوتر بعشرين، أو بأكثر؛ فلا بأس، الأمر واسع، كله سنة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17262/فضل-قيام-الليل-واحكامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73122.mp3","categories":["فضائل الأعمال","الوتر وقيام الليل"]},{"id":18310,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، بل من الأخت: ميسرة من العراق، بغداد، أختنا تسأل وتقول: هل هناك صلاة خاصة لحفظ القرآن الكريم؟ أم أكتفي بالدعاء عند الصلاة المفروضة بأن ييسر الله لي هذا الأمر؟ وإذا كانت هناك صلاة، فمتى يكون وقتها؟ جزاكم الله خيرًا.","title":"هل توجد صلاة خاصة لحفظ القرآن؟","answer":"الجواب: ليس لذلك صلاة، ولكن عليك الدعاء، الدعاء والضراعة إلى الله أن يعينك على حفظ القرآن الكريم، وعليك الاجتهاد في حفظه، في الأوقات المناسبة، التي يكون فيها القلب فارغًا، في أول النهار، أو في الليل، التمسي الأوقات المناسبة، واسألي الله العون على ذلك -سبحانه وتعالى- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17371/هل-توجد-صلاة-خاصة-لحفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73206.mp3","categories":["فضائل الأعمال","الأدعية والأذكار","القرآن وعلومه"]},{"id":18631,"question":"سمعت حديثًا عن رسول الله ﷺ معناه: أنه شهد لرجل بالجنة؛ وذلك لأنه كان يقول عندما يأوي إلى فراشه: اللهم إني عفوت عمن ظلمني، عفوت فاعف، سامحت فسامح، تجاوزت فتجاوز؛ أنت أجود وأكرم. و إذا كان أناس يؤذونك ويظلمونك وأذاهم مستمر، وتريد من الله  أن ينتقم لك منهم، ويصرف عنك كيدهم، هل هذا الدعاء يمنع أذاهم وظلمهم القائم؟","title":"الفضل العظيم لمن عفا عمن ظلمه","answer":"الجواب: إذا استجيب هذا الدعاء....، وحسن من المؤمن مع إخوانه أن يعفو ويصفح، كما قال الله : وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى [البقرة:237] وقال ﷺ: رحم الله امرًأ سمحًا إذا باع، سمحًا إذا اشترى، سمحًا إذا اقتضى وقال ﷺ: ما زاد الله عبدًا بعفو إلا عزًا، فإذا تسامح وعفا الإنسان عمن ظلمه، وتعدى عليه فهو مأجور، وإن طلب الانتقام ممن ظلمه، وقال: اللهم يسر لي الاقتصاص منه، اللهم خذ حقي منه؛ فلا حرج، قال الله تعالى: لا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148]. فالإنسان إذا طلب القصاص من ربه، أن الله يقتص له من هذا الرجل، وأن الله ينتقم له منه للحق الذي عليه، وأن ينصف له منه، فلا حرج في ذلك، يسأل ربه أن ينصفه، وأن يكف أذاه عنه، لكن إذا عفا وصفح ودعا له هذا خير عظيم ودرجة عظيمة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17740/الفضل-العظيم-لمن-عفا-عمن-ظلمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73416.mp3","categories":["فضائل الأعمال"]},{"id":19122,"question":"يسأل أخونا سؤالًا ثانٍ ويقول: هل الصلاة في الصف الأول في المسجد لها شيء من الفضل عن باقي الصفوف، أو عن الصف الخلفي؟ أرشدوني أفادكم الله.","title":"أفضلية الصلاة في الصف الأول على بقية الصفوف","answer":"الجواب: نعم الصف الأول أفضل؛ ولهذا قال عليه الصلاة والسلام: لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا، يعني: لاقترعوا، فله فضل عظيم، وجاء في بعض الأحاديث أنه يكون له مثل أجور من خلفه من الصفوف، يكون له أجره مقدم على غيره، ويكون له مثل أجور من خلفه؛ لأنه كالقائد لهم، وكالإمام لهم، والرسول يقول ﷺ: من دل على خير فله مثل أجر فاعله. فالصف الأول له مثل أجور من خلفه، مع أجره الذي كتبه الله له  هذا فضل عظيم، ولما فيه من المسابقة إلى الخيرات، والمسارعة إلى الطاعات، والقرب من الإمام حتى يشاهد حركاته لو انقطع الصوت، أو ضعف الصوت؛ فإنه يشاهد ويرى الإمام ويقرب منه. فالحاصل أن الصف الأول له فضل عظيم، لما في التوجه إليه من المسابقة إلى الخيرات، والمسارعة إلى الطاعات، وتحريض الناس على ذلك، وتشجيعهم على ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18318/افضلية-الصلاة-في-الصف-الاول-على-بقية-الصفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88508.mp3","categories":["فضائل الأعمال","قضايا المرأة","صلاة الجماعة"]},{"id":19326,"question":"شيخ عبد العزيز مناسبة يهتبلها البرنامج، تلكم هي الحديث عن بر الوالدين، كيف يعين الأب أبناءه على البر به؟ وكيف يكون الأبناء تجاه الوالدين؟ لو تكرمتم.","title":"أهمية بر الوالدين","answer":"الجواب: بر الوالدين من أهم الواجبات ومن أعظم الفرائض، وقد قرن الله حق الوالدين بحقه سبحانه بالتوحيد حيث قال جل وعلا في كتابه العظيم: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23]، قضى معنى: أمر وأوصى، فأوصى سبحانه عباده أن لا يعبدوا إلا إياه أن يخصوه بالعبادة، ثم قال: وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23]. فجعل حق الوالدين مع حقه ، ومعلوم أن حقه هو أعظم الفرائض وهو التوحيد، فدل ذلك على أن بر الوالدين من أهم الفرائض، وقال : أنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]، فجعل شكر الوالدين مع شكره ، فدل ذلك على عظم حقهما، وقال في الحديث الصحيح يقول النبي ﷺ: ألا أنبئكم بأكبر الكبائر؟ -ثلاث مرات- قلنا: بلى يا رسول الله، قال: الإشراك بالله، وعقوق الوالدين، وكان متكئًا فجلس، فقال: ألا وقول الزور ألا وشهادة الزور متفق على صحته، فجعل العقوق قرين الشرك كما أن البر قرين التوحيد ثم جعل بعد ذلك شهادة الزور هي أكبر الكبائر بعد الشرك والعقوق. فالواجب على الأولاد ذكورًا كانوا أو إناثًا أن يتقوا الله، وأن يخلصوا لله العبادة، وأن يستقيموا على طاعته سبحانه، وأن يبروا والديهم أحياء أو أمواتًا بالكلام الطيب، بالدعاء، بالصدقة عنهم، إلى غير هذا، وفي حياتهم بالسمع والطاعة في المعروف والقيام بحقهم، إلى غير هذا مما يجب لهم في الحياة من النفقة إن كانوا محاويج، وكف الأذى وعدم السب والشتم، وعدم أي أذى، هذا هو الواجب على الولد مع والديه، وقد سئل ﷺ قيل: يا رسول الله! هل بقي من بر والدي شيء أبرهما به بعد وفاتهما؟ قال له: نعم. الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وصلة الرحم التي لا توصل إلا بهما، وإكرام صديقهما، أخبر ﷺ عن خمسة أمور كلها من بر الوالدين بعد وفاة الوالدين: فالأول والثاني: الصلاة عليهما والاستغفار كونه يصلي عليهما؛ يعني: يدعو لهما يترحم عليهما ويكثر من الاستغفار لهما، ويدخل في ذلك صلاة الجنازة كونه يصلي عليهما صلاة الجنازة. الثالث: إنفاذ عهدهما من بعدهما يعني: الوصية التي يوصيان بها ينفذها الولد إذا كانت شرعية، عليه أن ينفذها إذا كانت مما يوافق الشرع المطهر كوصية الوالد أو الوالدة بالصدقة على الفقراء.. بضحية.. بحجة.. بتعمير مسجد.. بغير هذا مما شرعه الله إذا كان ذلك يخرج من الثلث، أما إذا كان زائد على الثلث فلابد من أن يجعل ميراثًا لكن ما دامت الوصية بالثلث فأقل فالواجب تنفيذها والحرص على إنجاز ذلك؛ لأن هذا من إنفاذ عهدهما من بعدهما. وهكذا كل وصية تنفعهما ولا تخالف الشرع المطهر فمن برهما إنفاذها كما لو أوصيا بأن يجتهد أبناؤهما الكبار في الإحسان إلى أبنائهم الصغار أبنائهما أو بناتهما، أو أوصيا بإكرام أخيهما أو أختهما أو إخوتهما أو أخواتهما، أو أوصيا بإكرام فلان أو فلانة من أجل الصداقة التي بينهما وبينه ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/18535/اهمية-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_896/nour_89604.mp3","categories":["فضائل الأعمال"]},{"id":19345,"question":"....من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل مع الأخ من اليمن عن الترضية عن الصحابة  فأخونا من بغداد الزعفرانية محمود أحمد الدوسة يقول: هل الترضي عن الصحابة رضوان الله عليهم واجب أم سنة؟ كما يسأل نفس السؤال بالنسبة للصلاة على النبي ﷺ.أما أخونا محمد محمود النهاري من الحديدة، فيسأل نفس السؤال تقريبًا في كلمات تعطي نفس المعنى، ويقول: إن هناك من ينتقد الترضي على الصحابة رضوان الله عليهم والصلاة على النبي ﷺ ولاسيما في خطب الجمعة، نرجو من سماحة الشيخ أن يوجه الأخوين محمد محمود النهاري من الحديدة، وأخونا محمود من العراق، جزاكم الله خيرًا.","title":"بيان فضل الصلاة على النبي والترضي عن أصحابه","answer":"الجواب: الصلاة على النبي ﷺ من أفضل القربات ومن أهم الطاعات في الخطب وفي غير الخطب، يقول الله  في كتابه العظيم: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] صلى الله وسلم عليه وعلى آله وأصحابه صلاة وسلامًا دائمين إلى يوم الدين.\nويقول عليه الصلاة والسلام: من صلى علي واحدة صلى الله عليه بها عشرًا. في أحاديث كثيرة تدل على شرعية الصلاة والسلام عليه الصلاة والسلام، ولما سأله الصحابة قالوا: يا رسول الله! أمرنا الله أن نصلي عليك فكيف نصلي عليك؟ قال: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، وبارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، هذا أكمل ما ورد في هذا، وجاءت بألفاظ أخرى في بعضها اختصار ومنها: اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم، وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد. وهكذا لفظ آخر: يقول عليه الصلاة والسلام: قولوا: اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد رواه مسلم في صحيحه، والأولان رواهما الشيخان في الصحيحين. فالمقصود أن هذه الأنواع كلها من الأنواع المشروعة التي جاء بها النص عن النبي عليه الصلاة والسلام، فينبغي للمؤمن الإكثار من الصلاة والسلام على النبي عليه الصلاة والسلام في الصلاة وفي خارج الصلاة وفي الخطب خطب الجمعة والأعياد والخطب العادية في المجامع هكذا ينبغي للمؤمن، والله جل وعلا أمره بهذا ووعده عليها خيرًا كثيرًا، من صلى علي واحدة صلى الله عليه به عشرًا. وأما الترضي عن الصحابة فهو أمر مشروع أيضًا؛ لأن الصحابة هم حملة الإسلام، هم حملة الشريعة، وهم خير هذه الأمة وأفضلها، كما قال عليه الصلاة والسلام: خير أمتي قرني ثم الذين يلونهم ثم الذين يلونهم رواه البخاري ومسلم في الصحيحين من حديث ابن مسعود. وفي اللفظ الآخر: خير أمتي قرني ثم الذين يلونهم ثم الذين يلونهم رواه البخاري في الصحيح ورواه مسلم أيضًا، والأحاديث في هذا كثيرة كلها دالة على أن الصحابة هم أفضل الناس وهم خير الناس بعد الأنبياء عليهم الصلاة والسلام، وأفضلهم وأعلاهم قدرًا أبو بكر الصديق رضي الله تعالى عنه، ثم يليه في الفضل عمر بن الخطاب الفاروق ، ثم يليه في الفضل عثمان بن عفان ، ثم يلي الثلاثة في الفضل علي بن أبي طالب رضي الله تعالى عنه، ثم بقية العشرة من .... طلحة بن عبيد الله التيمي و الزبير بن العوام الأسدي أسد قريش وعبد الرحمن بن عوف الزهري، وسعد بن مالك سعد بن أبي وقاص الزهري، وسعيد بن زيد ابن عم عمر رضي الله تعالى عنهم أجمعين، والعاشر أبو عبيدة بن الجراح، هؤلاء من أفضل الصحابة بعد الخلفاء، هم أفضل الصحابة بعد الخلفاء ، فالترضي عنهم من أهم المهمات ومن أفضل القربات، والواجب حبهم في الله واعتقاد أن الصحابة أفضل الناس بعد الأنبياء والمرسلين هم أفضل الناس، كما قال ﷺ: خير الناس قرني.. خير أمتي قرني فهم خير الناس وهم خير الأمة. فالواجب على المؤمن أن لا يكون في قلبه غل لهم، بل يحبهم في الله محبة صادقة فوق محبة أهله وأولاده والناس أجمعين بعد محبة الأنبياء، الأنبياء ثم يليهم الصحابة، ويخص الخلفاء الراشدين بمزيد محبة، وهم الصديق وعمر وعثمان وعلي، هؤلاء الأربعة هم أفضل الصحابة، وأن يحذر أن يكون في قلبه غل للصديق أو عمر أو عثمان كما فعلت الرافضة ومن شابههم من بعض فرق الشيعة، بل يجب أن يحبهم في الله وأن يعتقد أنهم أفضل الصحابة وأن عليًا  وأرضاه هو رابعهم وهو أمير المؤمنين ومناقبه كثيرة وأعماله الطيبة كثيرة لكن لا يجوز أن يغلى فيه كما تفعل الرافضة، أو يقال فيه: إنه يعلم الغيب أو إنه معصوم أو إنه أفضل من الثلاثة هذا كله منكر كله لا يجوز ولاسيما القول بأنه أفضل من الصديق وعمر هذا أشد. أما كونه أفضل من عثمان هذا قول بعض أهل السنة والخلاف فيه مشهور، لكن الذي عليه جمهور أهل السنة أن عثمان هو المقدم، ثم علي رضي الله عن الجميع، فالواجب على المؤمن وعلى المؤمنة أينما كانا في أرض الله حب الصحابة  وتوليهم والترضي عنهم وإنزالهم منازلهم، وأن لا يصيبه ما أصاب الرافضة من الغل والحقد على الصحابة؛ فإن قول الرافضة في هذا منكر عظيم لا يجوز موافقتهم عليه ولا تقليدهم فيه، بل قد ضلوا فيه عن سواء السبيل. فـأهل السنة والجماعة يرون أن الصديق هو أفضلهم، وقد دلت عليه النصوص الكثيرة وأجمع عليه المسلمون، ثم بعده عمر الفاروق رضي الله عنهما جميعًا، وقد أقر بهذا علي ، خطب بذلك على رءوس الأشهاد وتواتر عنه  أنه قال: خير هذه الأمة بعد نبيها أبو بكر ثم عمر، قد سأله عنه ذلك ابنه محمد بن علي فخطب بهذا على رءوس الأشهاد، وقال: لا أوتى بأحد يفضلني على الصديق وعمر إلا جلدته حد المفتري، هكذا يقول هذا الإمام العظيم علي  لعلمه بأهل الحق ولإنصافه، وإنما يعرف الحق لأهل الحق الفضلاء، فلا يعرف الفضل لأهله إلا ذوو الفضل، فهو  عرف فضل الصديق وعمر وفضل عثمان ولم ينقم أن فضل عليه الصديق وعمر، وهكذا فضل عليه عثمان وبويع له وبايع الناس معه، وبايع الناس لـعثمان بايع علي  مع الناس لـعثمان لما بايعه المسلمون وساعده في خلافته رضي الله عن الجميع. وإنما شذ عن هذا من أبعدهم الله بعقيدتهم الفاسدة من الرافضة، فيجب على المؤمن أن يحذر قولهم وأن يستقيم على ما قاله أهل السنة والجماعة، وأن يحب الصحابة جميعًا ويترضى عنهم جميعًا، ويعتقد أنهم أفضل الخلق بعد الأنبياء، وأنهم حملة الشريعة، وأن القدح فيهم منكر عظيم، ولهذا قال ﷺ: لا تؤذوا أصحابي.. لا تؤذوني في أصحابي وقال عليه الصلاة والسلام: لو أن أحدكم أنفق مثل أحد ذهبًا ما بلغ مد أحدهم ولا نصيفه. لما جرى بين عبد الرحمن بن عوف وبين خالد بن الوليد بعض الشيء قال: لا تسبوا أصحابي، فوالذي نفسي بيده لو أنفق أحدكم مثل أحد ذهبًا ما بلغ مد أحدهم ولا نصيفه، هذا نص منه ﷺ في تحريم سبهم، فلا يجوز سب أحد منهم لا كبارهم ولا صغارهم، يجب الترضي عنهم ومحبتهم محبة صادقة والإيمان بأنهم خير الناس، وأفضل الناس بعد الأنبياء، ولا يجوز سب أحد منهم  وأرضاهم، ولهذا بين فضلهم عليه الصلاة والسلام فقال : لو أن أحدكم أنفق مثل أحد ذهبًا ما بلغ مد أحدهم ولا نصيفه بعدما نهى عن سبهم وقال: لا تسبوا أصحابي فهذا يدل على تحريم سبهم وأنه منكر عظيم، وأن نفقاتهم مضاعفة  وأرضاهم، وأن الواحد منا لو أنفق مثل أحد -هذا الجبل العظيم- ذهبًا ما بلغ مد أحدهم ولا نصيفه، فكيف يجوز لأحد بعد هذا أن يقدح فيهم أو يسبهم أو يعيبهم أو يتنقصهم؟! وإني أهيب بجميع الشيعة أهيب بهم جميعًا أن يرجعوا عما هم عليه من الباطل، وأن يتقوا الله، وأن يعرفوا قدر الصحابة ويترضوا عنهم جميعًا، وأن يوافقوا أهل السنة في الترضي عنهم ومحبتهم والإيمان بمنزلتهم عند الله وأنهم أصحاب رسوله عليه الصلاة والسلام، وأنهم نقلة الأخبار إلينا في التوحيد وفي الصلاة وفي الزكاة وفي الصيام وفي الحج وفي سائر أمور الدين، هم النقلة هم العدول  وأرضاهم، وعلي من جملتهم، وهكذا الحسن والحسين من جملتهم رضي الله عن الجميع. فالواجب محبتهم وإنزالهم منازلهم، والواجب على كل شيعي في أي أرض الله أن يتقي الله وأن يرجع إلى الحق، وأن يؤمن بالله وحده ويصدق رسوله فيما قال عليه الصلاة والسلام، وأن يوحد الله ويخصه بالعبادة، وأن لا يعبد أحدًا من أهل البيت لا علي ولا غيره، بل العبادة حق الله وحده ، وأن يعلم أن عليًا  وغيره من أهل البيت كلهم غير معصومين ولا يعلمون الغيب بل هم مثل غيرهم كـالصديق وعمر وعثمان وطلحة وغيرهم كلهم لا يعلمون الغيب، وكل واحد منهم قد يخطئ ليس بمعصوم ولكنهم مع هذا كله هم أفضل الناس وهم خير الناس. وما قد يقع من بعضهم من زلة أو خطيئة فله من الحسنات العظيمة والفضائل الكثيرة والقربات العظيمة ما نرجو أن يمحو الله به فيها زلته ويغفر بها خطيئته، وله من الفضل عند الله ما لا يدانيه فيه أحد. فالواجب على الشيعة وغيرهم أن يعرفوا منازل هؤلاء الأخيار، وأن يعظموهم كما عظمهم الله، وأن يعرفوا لهم فضلهم وأن يترضوا عنهم، وأن لا يغلوا في أهل البيت، وأن لا يعبدوا أحدًا منهم من دون الله، لا بالاستغاثة، ولا بالدعاء، ولا بالقول أنهم معصومون، أو أنهم يعلمون الغيب، أو القدح في إمرة الصديق أو إمرة عثمان أو عمر ، بل يجب عليهم جميعًا أن يأخذوا بمذهب أهل السنة، وأن يسيروا على مذهب أهل السنة، فهو الحق الذي لا ريب فيه، أما ما انتحلته الرافضة أو غيرهم من الشيعة بالتنقص من أصحاب النبي ﷺ فهو باطل ومنكر عظيم وشر مستطير، يجب عليهم أن يبادروا بالتوبة إلى الله منه في أسرع وقت قبل أن يموتوا، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا ونفع بعلمكم واستجاب منكم.","link":"https://binbaz.org.sa/fatwas/18544/بيان-فضل-الصلاة-على-النبي-والترضي-عن-اصحابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_898/nour_89801.mp3","categories":["فضائل الأعمال"]},{"id":19556,"question":"هذه الأخت السائلة أم أنس من حائل تقول: هل يلزم من حقوق الأخوة في الله دوام الاتصال بهم والسؤال عنهم، علمًا بأن الأخوات كثيرات والحمد لله، وأنا خائفة في التقصير في حقوقهن، وجهونا في ضوء الحب في الله، والبغض في الله يا سماحة الشيخ؟","title":"فضائل وحقوق الحب في الله عز وجل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فإن الحب في الله والبغض في الله من أهم خصال الإيمان، ومن أفضل خصال الإيمان، بل جاء في الحديث أنها أوثق عرى الإيمان، الحب في الله، والبغض في الله، ولكن لا يلزم دوام الاتصال، بل إذا دعا لهم بظهر الغيب، وزارهم بعض الأحيان، أو زاروه كان هذا من أفضل القربات، إذا كان ذلك لله .\nومن المحبة أن يسأل عنه إذا فقده، ويزوره إذا مرض، ويدعو له بالخير، هذا من المحبة، أما دوام الاتصال بالهاتف أو غيره فليس من شرط ذلك، لكن إذا كلمه بالهاتف أو زاره فهذا من ثمرات المحبة في الله جل وعلا في الأوقات المناسبة التي لا يحصل فيها إملال ولا إيذاء، بل في الأوقات المناسبة التي يحصل بها الدعاء، والتعارف، والتلاقي من غير أن يؤذي أحد أحدًا في كثرة اللقاء وكثرة السؤال. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18802/فضاىل-وحقوق-الحب-في-الله-عز-وجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94701.mp3","categories":["فضائل الأعمال"]}]
